def is_screen_protector_or_accessory_context(text: str) -> bool:
    """
    Returns True if the text is about screen protectors ('מגן מסך', 'מגיני מסך', 'מגן סיליקון', 'מגן זכוכית',
    'מגן פיברגלס', 'סיליקון פרימיום', 'מגן לאייפון') or store accessories, rather than a physical screen replacement lab repair ('החלפת מסך').
    """
    clean = auto_fix_common_hebrew_typos((text or "").lower())
    protector_terms = [
        "מגן מסך", "מגיני מסך", "מגני מסך", "מגן למסך", "מדבקת מסך", "מדבקה למסך",
        "מגן זכוכית", "מגן סיליקון", "סיליקון פרימיום", "מגן פיברגלס", "פיברגלס",
        "מגן ג'ל", "מגן הידרוג'ל", "מגן מאט", "מגן פרטיות", "מגן ננו",
        "מגן לאייפון", "מגן לגלקסי", "מגן לשיאומי", "סוגי מגינים", "סוגי מגנים",
        "איזה מגן", "איזה מגינים", "איזה מגנים", "מגינים", "מגנים"
    ]
    return any(t in clean for t in protector_terms)


def is_screen_protector_variety_inquiry(text: str) -> bool:
    """
    Returns True when a customer is asking what types/variety of screen protectors exist in stock
    (e.g. 'רוצה לבדוק מגן זכוכית לאייפון איזה סוגים יש', 'יש לכם מגיני מסך?', 'אילו סוגי מגנים יש?'),
    as opposed to asking the price of one specific sub-type like 'מה מחיר מגן הפיברגלס'.
    """
    clean = auto_fix_common_hebrew_typos((text or "").strip().lower())
    if not clean or not is_screen_protector_or_accessory_context(clean):
        return False
    # If customer specifically mentions Fiberglass, Silicone Premium, Privacy, Matte, Hydrogel etc. AND asks its price, it's a specific option inquiry
    specific_non_generic = ["פיברגלס", "סיליקון פרימיום", "פרטיות", "מאט", "הידרוג'ל", "ננו"]
    if any(s in clean for s in specific_non_generic) and any(p in clean for p in ["מחיר", "כמה", "עולה", "עלות", "להזמין את", "רוצה את"]):
        return False
    variety_signals = [
        "איזה סוגים", "אילו סוגים", "מה הסוגים", "איזה סוגי", "אילו סוגי",
        "איזה מגיני", "איזה מגנים", "אילו מגיני", "אילו מגנים", "איזה מגן יש",
        "יש לכם מגיני", "יש לכם מגן", "יש מגיני מסך", "יש מגן מסך", "מה המבחר", "איזה מבחר"
    ]
    if any(v in clean for v in variety_signals):
        return True
    # Also if the message is simply "מגיני מסך?" or "יש לכם מגיני מסך?"
    if any(w in clean for w in ["מגיני מסך", "מגני מסך"]) and not any(s in clean for s in specific_non_generic + ["סיליקון"]):
        return True
    return False


def detect_specific_option_name(text: str) -> str:
    """
    Identifies if a text refers to a specific option from KNOWN_OPTION_CATALOG
    (e.g. 'מה מחיר מגן הפיברגלס' -> 'מגן פיברגלס', 'מגן סיליקון פרמיום' -> 'מגן סיליקון פרימיום').
    Returns '' if the customer is asking for the general variety ('איזה סוגים יש').
    """
    clean = auto_fix_common_hebrew_typos((text or "").strip().lower())
    if not clean or is_screen_protector_variety_inquiry(clean):
        return ""
    for canon_name, kws in KNOWN_OPTION_CATALOG:
        if any(re.search(rf"(?:^|\s|[ובלמה,.-]){re.escape(k)}(?:$|\s|[,.!?:])", clean) for k in kws):
            return canon_name
    return ""


def is_price_or_comparison_question(text: str) -> bool:
    """
    Returns True if the customer is asking for the price/cost of an item or comparing prices
    (with or without a question mark '?'), e.g.:
    - 'מה מחיר מגן הפיברגלס'
    - 'כמה עולה המגן סיליקון פרמיום'
    - 'ומה לגבי הסיליקון פרימיום כדי להשוות מחירים'
    """
    clean = auto_fix_common_hebrew_typos((text or "").strip().lower())
    if not clean:
        return False
    price_q_terms = [
        "מחיר", "המחיר", "מחירים", "כמה עולה", "כמה זה", "כמה הוא", "מה העלות", "עלות",
        "להשוות", "בהשוואה", "לעומת", "ומה לגבי", "מה לגבי", "ומה עם", "מה עם"
    ]
    if any(t in clean for t in price_q_terms):
        return True
    if ("?" in clean or "؟" in clean) and detect_specific_option_name(clean):
        return True
    return False


def get_known_option_price(option_name: str, open_action_taken: str = "", recent_history: str = "") -> str:
    """
    Looks up the price of a specific option (e.g. 'מגן פיברגלס', 'מגן סיליקון פרימיום', 'מגן זכוכית') across:
    1. learned_item_prices table in SQLite
    2. pos_inventory table in SQLite
    3. open_action_taken ([OPTIONS_JSON:...], [LAST_QUOTED_ITEM:...], or text)
    4. recent_history of current chat
    5. learned_kb and ALL past customer_requests & conversation_history in SQLite!
    """
    if not option_name:
        return ""
    canon = detect_specific_option_name(option_name) or auto_fix_common_hebrew_typos(option_name).strip()
    stems = [canon.lower()]
    for c_name, kws in KNOWN_OPTION_CATALOG:
        if c_name == canon:
            stems = [k.lower() for k in kws]
            break

    # 1. Check learned_item_prices table first
    try:
        conn = sqlite3.connect(DB_PATH)
        row = conn.execute(
            "SELECT price_nis FROM learned_item_prices WHERE item_name = ? LIMIT 1",
            (canon,)
        ).fetchone()
        if row and row[0]:
            conn.close()
            return str(row[0]).strip()
        all_price_rows = conn.execute("SELECT item_name, price_nis FROM learned_item_prices").fetchall()
        conn.close()
        for r_name, r_price in all_price_rows:
            if r_name and r_price and (r_name == canon or any(s in r_name.lower() for s in stems)):
                return str(r_price).strip()
    except Exception:
        pass

    # 2. Check [LAST_QUOTED_ITEM:...] [LAST_QUOTED_PRICE:...] in open_action_taken
    if open_action_taken:
        for m_lq in re.finditer(r"\[LAST_QUOTED_ITEM:([^\]]+)\]\s*\[LAST_QUOTED_PRICE:(\d{2,4})\]", open_action_taken):
            if m_lq.group(1).strip() == canon:
                return m_lq.group(2).strip()

    # 3. Check options extracted from open_action_taken and recent_history
    for src in [open_action_taken or "", recent_history or ""]:
        if not src:
            continue
        for opt in extract_options_and_prices_from_text(src):
            if opt["name"] == canon and opt.get("price"):
                return str(opt["price"]).strip()

    # 4. Scan learned_kb, customer_requests, and conversation_history across the entire database!
    try:
        conn = sqlite3.connect(DB_PATH)
        kb_rows = conn.execute("SELECT keywords, answer FROM learned_kb ORDER BY id DESC").fetchall()
        req_rows = conn.execute("SELECT request_text, action_taken FROM customer_requests ORDER BY id DESC LIMIT 40").fetchall()
        hist_rows = conn.execute("SELECT message FROM conversation_history WHERE role='agent' ORDER BY id DESC LIMIT 60").fetchall()
        conn.close()

        candidate_texts = []
        for kw_s, ans_s in kb_rows:
            candidate_texts.append(f"{kw_s or ''} : {ans_s or ''}")
        for rq_s, ac_s in req_rows:
            candidate_texts.append(f"{rq_s or ''} | {ac_s or ''}")
        for (h_msg,) in hist_rows:
            candidate_texts.append(h_msg or "")

        for blob in candidate_texts:
            blob_clean = auto_fix_common_hebrew_typos(blob).replace("052-4043644", " ").replace("0524043644", " ")
            for opt in extract_options_and_prices_from_text(blob_clean):
                if opt["name"] == canon and opt.get("price"):
                    return str(opt["price"]).strip()
            # Also check if a stem appears near a price on the same line
            for st in stems:
                if len(st) < 3:
                    continue
                m_near = (
                    re.search(rf"{re.escape(st)}[^\n0-9,;]{{0,35}}?(\d{{2,4}})\s*(?:₪|ש\"ח|שח|שקל)", blob_clean, re.IGNORECASE)
                    or re.search(rf"{re.escape(st)}\s*(?:הוא|עולה|במחיר|ב-?|[:=-])\s*\*?(\d{{2,4}})\b", blob_clean, re.IGNORECASE)
                )
                if m_near:
                    val = int(m_near.group(1))
                    if 15 <= val <= 2500:
                        return str(val)
    except Exception:
        pass

    return ""


def extract_options_and_prices_from_text(text: str) -> list:
    """
    Extracts multiple product/accessory options and their prices from Admin replies, KB answers,
    or conversation history.
    Handles both options with prices ('מגן זכוכית 40, מגן סיליקון פרימיום 100') AND option lists without prices
    ('יש מגן זכוכית, מגן פיברגלס ומגן סיליקון פרימיום').
    Returns list of dicts: [{"name": str, "price": str, "keywords": list[str]}]
    """
    if not text:
        return []
    cleaned = auto_fix_common_hebrew_typos(text)
    # Remove metadata tags before parsing text segments
    cleaned_no_tags = re.sub(
        r"\[(?:OPTIONS_JSON|PRICE|GALUT_PRICE|YEMOT_PRICE|PROPOSED_TIME|COLOR|TARGET_ITEM|LAST_QUOTED_ITEM|LAST_QUOTED_PRICE):[^\]]*\]",
        " ",
        cleaned
    )
    cleaned_no_tags = cleaned_no_tags.replace("052-4043644", " ").replace("0524043644", " ").replace("055-3164770", " ")

    options = []
    seen_names = set()

    # 1. First merge any embedded [OPTIONS_JSON:...]
    for m_json in re.finditer(r"\[OPTIONS_JSON:(\[.*?\])\]", text):
        try:
            parsed = json.loads(m_json.group(1))
            if isinstance(parsed, list):
                for item in parsed:
                    if isinstance(item, dict) and item.get("name"):
                        nm = auto_fix_common_hebrew_typos(item["name"])
                        if nm not in seen_names:
                            seen_names.add(nm)
                            options.append({
                                "name": nm,
                                "price": str(item.get("price") or ""),
                                "keywords": item.get("keywords") or [nm],
                            })
                        elif item.get("price"):
                            for ex in options:
                                if ex["name"] == nm and not ex.get("price"):
                                    ex["price"] = str(item["price"])
        except Exception:
            pass

    # 2. Split text into segments by newline, comma, semicolon, bullet, ' או ', or ' ו-'
    raw_segments = re.split(
        r"[\n,;•●]|\s+או\s+|\s+ו(?=(?:מגן|יש|זכוכית|סיליקון|פיברגלס|פרטיות|מאט|הידרוג|ננו|פשוט))",
        cleaned_no_tags
    )
    for seg in raw_segments:
        seg_s = seg.strip()
        if not seg_s:
            continue
        if any(w in seg_s for w in ["מסלול גלות", "ימות המשיח", "מסלול גאולה"]):
            continue

        m_pr = (
            re.search(r"\b(\d{2,4})\s*(?:₪|ש\"ח|ש''ח|שח|שקלים|שקל)\b", seg_s)
            or re.search(r"(?:ב-|ב\s*|מחיר\s*|עולה\s*|עלות\s*|הוא\s*|[-:])\s*\*?(\d{2,4})\b", seg_s)
            or re.search(r"\b(\d{2,3})\b", seg_s)
        )
        price_val = ""
        if m_pr:
            cand_p = int(m_pr.group(1))
            if 15 <= cand_p <= 3500 and (cand_p != 100 or ("100" in seg_s and "תוספת" not in seg_s)):
                price_val = str(cand_p)

        matched_canon = None
        matched_kws = []
        for canon_name, kws in KNOWN_OPTION_CATALOG:
            if any(re.search(rf"(?:^|\s|[ובלמה,.*-]){re.escape(k)}(?:$|\s|[,.!?:*])", seg_s.lower()) for k in kws):
                matched_canon = canon_name
                matched_kws = kws
                break

        if matched_canon:
            if matched_canon not in seen_names:
                seen_names.add(matched_canon)
                options.append({
                    "name": matched_canon,
                    "price": price_val,
                    "keywords": matched_kws,
                })
            elif price_val:
                for ex in options:
                    if ex["name"] == matched_canon:
                        ex["price"] = price_val
        elif price_val:
            label_clean = re.sub(r"\b\d{2,4}\s*(?:₪|ש\"ח|ש''ח|שח|שקלים|שקל)?\b", "", seg_s)
            label_clean = re.sub(
                r"^(?:יש\s+לנו|יש|ויש|או|חזרתי\s+אליך\s+בנוגע\s+לפנייתך:?|המחיר\s+המדויק\s+הוא|המחיר\s+של|ב-|ב|עולה|מחיר|הוא)\s*",
                "",
                label_clean.strip(" -•:.,*")
            ).strip(" -•:.,*")
            if 2 <= len(label_clean) <= 32 and not any(q in label_clean for q in ["מה תרצה", "האם תרצה", "תרצה להזמין", "נשארו יחידות"]):
                if label_clean not in seen_names:
                    seen_names.add(label_clean)
                    kws = [w for w in label_clean.split() if len(w) >= 2]
                    options.append({
                        "name": label_clean,
                        "price": price_val,
                        "keywords": [label_clean] + kws,
                    })

    # 3. Fill in any missing prices from learned_item_prices table if available
    try:
        conn = sqlite3.connect(DB_PATH)
        price_map = dict(conn.execute("SELECT item_name, price_nis FROM learned_item_prices").fetchall())
        conn.close()
        for opt in options:
            if not opt.get("price") and opt["name"] in price_map and price_map[opt["name"]]:
                opt["price"] = str(price_map[opt["name"]])
    except Exception:
        pass

    return options


def find_selected_option_and_price(customer_msg: str, open_action_taken: str = "", recent_history: str = "", open_req_text: str = "") -> dict:
    """
    Checks if the customer is naming/selecting a specific option to ORDER (e.g. 'אני רוצה להזמין את הסיליקון',
    'תזמין לי פיברגלס', 'את הזכוכית', 'הסיליקון פרימיום') and looks up its price across all sources.
    IMPORTANT: Never triggers order selection when the customer is asking a price or comparison question
    ('מה מחיר מגן הפיברגלס', 'כמה עולה הסיליקון פרמיום להשוות מחירים')!
    Returns {"matched": bool, "name": str, "price": str, "all_options": list}
    """
    clean_msg = auto_fix_common_hebrew_typos((customer_msg or "").strip().lower())
    if not clean_msg:
        return {"matched": False, "all_options": []}

    # Gather all options mentioned anywhere in open_action_taken, recent_history, open_req_text, or learned_kb
    combined_sources = [open_action_taken or "", recent_history or "", open_req_text or ""]
    try:
        conn = sqlite3.connect(DB_PATH)
        kb_rows = conn.execute("SELECT answer FROM learned_kb ORDER BY id DESC LIMIT 20").fetchall()
        conn.close()
        for r in kb_rows:
            if r and r[0] and any(w in r[0] for w in ["מגן", "סיליקון", "זכוכית", "פיברגלס", "פרטיות", "מאט"]):
                combined_sources.append(r[0])
    except Exception:
        pass

    merged_options = {}
    for src in combined_sources:
        for opt in extract_options_and_prices_from_text(src):
            nm = opt["name"]
            if nm not in merged_options:
                merged_options[nm] = opt
            elif not merged_options[nm].get("price") and opt.get("price"):
                merged_options[nm]["price"] = opt["price"]

    all_opts = list(merged_options.values())

    # CRITICAL: Never treat a price question, comparison question, or recommendation question as an order command!
    if is_price_or_comparison_question(clean_msg) or "?" in clean_msg or "؟" in clean_msg or any(q in clean_msg for q in [
        "ממליץ", "מומלץ", "עדיף", "הבדל", "מה זה", "איזה מגן כדאי", "איזה סוגים יש", "אילו סוגים"
    ]):
        return {"matched": False, "all_options": all_opts}

    # Check if customer explicitly named an option from KNOWN_OPTION_CATALOG
    chosen_canon = detect_specific_option_name(clean_msg)
    if chosen_canon:
        price_found = ""
        if chosen_canon in merged_options and merged_options[chosen_canon].get("price"):
            price_found = merged_options[chosen_canon]["price"]
        if not price_found:
            price_found = get_known_option_price(chosen_canon, open_action_taken, recent_history)
        return {
            "matched": True,
            "name": chosen_canon,
            "price": price_found,
            "all_options": all_opts,
        }

    # Check against any custom options extracted into all_opts
    for opt in all_opts:
        for kw in opt.get("keywords", []):
            if len(kw) >= 2 and re.search(rf"(?:^|\s|[ובלמה,.-]){re.escape(kw.lower())}(?:$|\s|[,.!?:])", clean_msg):
                p_val = opt.get("price") or get_known_option_price(opt["name"], open_action_taken, recent_history)
                return {
                    "matched": True,
                    "name": opt["name"],
                    "price": p_val,
                    "all_options": all_opts,
                }

    return {"matched": False, "all_options": all_opts}


def is_admin_bit_payment_directive(text: str) -> bool:
    """
    Detects when Admin (Eran) hints or instructs the bot to send a Bit payment request to the customer
    (e.g. 'אתה צריך לשלוח ללקוח בקשה לשלוח ביט', 'תשלח ללקוח בקשה לשלוח ביט', 'שלח לו ביט', 'תבקש ממנו להעביר בביט').
    Never forwards these operational instructions raw to the customer!
    """
    clean = auto_fix_common_hebrew_typos((text or "").strip().lower())
    if not clean or ("ביט" not in clean and "bit" not in clean):
        return False
    directive_patterns = [
        r"(?:צריך|אמור|עליך)\s+(?:לשלוח|לבקש|לכתוב|לרשום|להגיד)",
        r"(?:תשלח|שלח|תבקש|בקש|תכתוב|תרשום|תגיד|תמסור)\s+(?:ללקוח|לו|לה|ממנו|מהלקוח)",
        r"בקשה\s+(?:לשלוח|להעביר|לתשלום)\s+(?:ב?ביט|bit)",
        r"(?:לשלוח|להעביר)\s+(?:ללקוח|לו)\s+(?:בקשת\s+תשלום|פרטי\s+ביט|בקשה\s+לביט|ביט)",
    ]
    return any(re.search(p, clean) for p in directive_patterns)


def is_admin_style_or_tikun_command(text: str) -> bool:
    """
    Detects when Admin writes 'תיקון:' or instructs the bot to permanently change its phrasing/style
    (e.g., 'תיקון: ...', 'מעכשיו אל תשאל את הלקוח אם הוא רוצה להזמין את החלק אלא תכתוב לו מה תרצה להזמין?',
    'במקום לכתוב X תכתוב Y').
    """
    clean = auto_fix_common_hebrew_typos((text or "").strip())
    if not clean:
        return False
    if re.match(r"^(?:תיקון|כלל\s+חדש|כלל\s+קבוע|שינוי\s+נוסח|נוסח\s+קבוע)\s*[:\-]", clean, flags=re.IGNORECASE):
        return True
    style_patterns = [
        r"מעכשיו\s+(?:אל|לא)\s+(?:תשאל|ישאל|תכתוב|יכתוב|תרשום|ירשום|תגיד|יגיד)",
        r"מעכשיו\s+(?:תכתוב|יכתוב|תרשום|ירשום|תשאל|ישאל)\s+(?:ללקוח|לו)?",
        r"במקום\s+(?:לשאול|לכתוב|לרשום|להגיד)\s+.+\s+(?:תכתוב|תרשום|תשאל|תגיד|יכתוב|ירשום)",
        r"(?:אל|לא)\s+(?:תשאל|ישאל)\s+(?:את\s+הלקוח\s+|אותו\s+)?אם\s+(?:הוא\s+)?רוצה\s+להזמין.+אלא",
        r"תשנה\s+את\s+הנוסח\s+באופן\s+קבוע",
        r"מתקן\s+את\s+הנוסח\s+באופן\s+קבוע",
    ]
    return any(re.search(p, clean, flags=re.IGNORECASE) for p in style_patterns)


def strip_admin_meta_coaching(text: str) -> str:
    """
    Separates and strips ALL Admin-to-Bot meta-scolding, memory/learning remarks, and meta-directives
    BEFORE any pronoun replacement runs, leaving ONLY the factual content intended for the customer!
    Examples handled:
    - 'כבר עניתי לו על השאלה הזאת והוא היה צריך ללמוד ממנה ושיש שחור ושיש לבן' -> 'יש שחור ויש לבן'
    - 'כבר עניתי לך אתה צריך ללמוד יש שחור ויש לבן' -> 'יש שחור ויש לבן'
    - 'תפנים את התשובה ותלמד לפעם הבאה שיש שחור ולבן' -> 'יש שחור ולבן'
    """
    if not text:
        return ""
    cleaned = text.strip()

    # 1. Strip full meta-scolding prefixes about already answering / needing to learn / repeating questions
    meta_prefix_patterns = [
        r"^(?:כבר\s+)?(?:עניתי|אמרתי|כתבתי|רשמתי|הסברתי|מסרתי)\s+(?:לך|לו|לסוכן)\s*(?:על\s+השאלה\s+הזאת|על\s+זה|את\s+זה|פעמיים|מקודם)?\s*(?:ו?(?:אתה|הוא|הסוכן)?\s*(?:היית|היה)?\s*(?:צריך|אמור)\s+(?:ללמוד|לזכור|להפנים|לדעת)(?:\s+ממנה|\s+מזה|\s+את\s+זה)?)?[.,!:\s]*",
        r"^(?:ו?(?:אתה|הוא|הסוכן)?\s*(?:היית|היה)?\s*(?:צריך|אמור)\s+(?:ללמוד|לזכור|להפנים|לדעת)(?:\s+ממנה|\s+מזה|\s+את\s+זה)?)[.,!:\s]*",
        r"^(?:למה\s+(?:אתה|הוא)\s+(?:שואל|מעביר)(?:\s+אלי|\s+אותי)?\s+שוב|שוב\s+(?:אתה|הוא)\s+שואל)[.,!:\s]*",
        r"^(?:תלמד(?:\s+מזה|\s+ממנה)?|תפנים(?:\s+את\s+התשובה)?|תזכור(?:\s+את\s+זה)?)[.,!:\s]*",
    ]
    changed = True
    while changed:
        changed = False
        for pat in meta_prefix_patterns:
            new_c = re.sub(pat, "", cleaned, flags=re.IGNORECASE).strip()
            if new_c != cleaned:
                cleaned = new_c
                changed = True

    # 2. Also strip any inline meta-clauses about learning/already answering anywhere in the sentence
    inline_meta_patterns = [
        r"(?:כבר\s+)?(?:עניתי|אמרתי|כתבתי|רשמתי|הסברתי)\s+(?:לך|לו|לסוכן)(?:\s+על\s+השאלה\s+הזאת|\s+על\s+זה|\s+את\s+זה)?[.,!\s]*",
        r"\b(?:ו?(?:אתה|הוא|הסוכן)?\s*(?:היית|היה)?\s*(?:צריך|אמור)\s+(?:ללמוד|לזכור|להפנים|לדעת)(?:\s+ממנה|\s+מזה|\s+את\s+זה)?)[.,!\s]*",
        r"\b(?:תלמד\s+מזה|תלמד\s+ממנה|תפנים\s+את\s+התשובה|אתה\s+צריך\s+ללמוד|הוא\s+צריך\s+ללמוד)[.,!\s]*",
    ]
    for pat in inline_meta_patterns:
        cleaned = re.sub(pat, " ", cleaned, flags=re.IGNORECASE).strip()

    # 3. Clean up leading connectors left behind after stripping meta-clauses (e.g., "ושיש שחור ושיש לבן" -> "יש שחור ויש לבן")
    cleaned = re.sub(r"^(?:וש-|ש-|ו-|אז\s+|כי\s+|ש(?=(?:יש|אין|המכשיר|אפשר|ניתן|זה|הוא))|וש(?=(?:יש|אין|המכשיר|אפשר|ניתן|זה|הוא)))\s*", "", cleaned).strip()
    cleaned = re.sub(r"^ו(?=(?:יש|אין)\b)", "", cleaned).strip()

    # 4. Fix common Hebrew typing glitches in Admin replies (e.g. "וישיש" -> "ויש", "סליקון" -> "סיליקון", "אלה" -> "אלא")
    cleaned = auto_fix_common_hebrew_typos(cleaned)
    cleaned = re.sub(r"^שיש\s+", "יש ", cleaned)

    return cleaned.strip(" ,.:;-")


def sanitize_admin_leakage(text: str) -> str:
    """
    Final ironclad outgoing customer-message safety sanitizer.
    Guarantees that NO internal Admin-to-Bot meta-criticism ('נתת ללקוח', 'עשית טעות', 'טעית', 'שגוי',
    'כבר עניתי לך', 'צריך ללמוד', 'ללמוד ממנה') or 3rd-person customer reference ('ללקוח', 'הלקוח')
    ever leaks to a customer in any code path!
    """
    if not text:
        return ""
    cleaned = text
    # Strip any leaked memory/learning scolding
    cleaned = re.sub(
        r"(?:כבר\s+)?(?:עניתי|אמרתי|כתבתי|רשמתי|הסברתי)\s+(?:לך|לו|לסוכן)(?:\s+על\s+השאלה\s+הזאת|\s+על\s+זה|\s+את\s+זה)?[.,!\s]*",
        "",
        cleaned,
        flags=re.IGNORECASE
    )
    cleaned = re.sub(
        r"\b(?:ו?(?:אתה|הוא|הסוכן)?\s*(?:היית|היה)?\s*(?:צריך|אמור)\s+(?:ללמוד|לזכור|להפנים|לדעת)(?:\s+ממנה|\s+מזה|\s+את\s+זה)?)[.,!\s]*",
        "",
        cleaned,
        flags=re.IGNORECASE
    )
    # Strip any leaked admin price error meta-criticism clauses
    cleaned = re.sub(
        r"(?:נכון\s*,?\s*)?(?:המחיר\s+)?(?:שנתת|שרשמת|שכתבת|שאמרת|ששלחת|שמסרת)(?:\s+ללקוח|\s+לו)?\s+(?:הוא\s+)?(?:שגוי|לא\s+נכון|מוטעה)(?:\s+ו?(?:עשית\s+טעות|טעית)(?:\s+של\s*\d+\s*(?:₪|ש\"ח|שח|שקל)?)?)?[.,!\s]*",
        "סליחה על הבלבול מקודם! בדקתי שוב מול ערן והנה הפרטים המעודכנים: ",
        cleaned,
        flags=re.IGNORECASE
    )
    cleaned = re.sub(
        r"\b(?:עשית\s+טעות|טעית(?:\s+במחיר)?|התבלבלת(?:\s+במחיר)?)(?:\s+של\s*\d+\s*(?:₪|ש\"ח|שח|שקל)?)?[.,!\s]*",
        "סליחה על הבלבול מקודם! ",
        cleaned,
        flags=re.IGNORECASE
    )
    cleaned = re.sub(r"\bוישיש\b", "ויש", cleaned)
    cleaned = re.sub(r"\bושיש\b", "ויש", cleaned)
    # Replace any remaining 2nd-person bot verbs + ללקוח / לו
    cleaned = re.sub(r"\b(?:שנתת|שרשמת|שכתבת|שאמרת|ששלחת)\s+(?:ללקוח|לו)\b", "שנמסר קודם", cleaned, flags=re.IGNORECASE)
    cleaned = re.sub(r"\b(?:נתת|רשמת|כתבת|אמרת|שלחת)\s+(?:ללקוח|לו)\b", "נמסר קודם", cleaned, flags=re.IGNORECASE)
    # Replace any remaining 3rd-person "ללקוח" / "הלקוח"
    cleaned = re.sub(r"\bאם\s+הלקוח\s+רוצה\b", "אם אתה רוצה", cleaned, flags=re.IGNORECASE)
    cleaned = re.sub(r"\bאם\s+הלקוח\s+מעוניין\b", "אם אתה מעוניין", cleaned, flags=re.IGNORECASE)
    cleaned = re.sub(r"\bעבור\s+הלקוח\b", "עבורך", cleaned, flags=re.IGNORECASE)
    cleaned = re.sub(r"\bשל\s+הלקוח\b", "שלך", cleaned, flags=re.IGNORECASE)
    cleaned = re.sub(r"\bאת\s+הלקוח\b", "אותך", cleaned, flags=re.IGNORECASE)
    cleaned = re.sub(r"\bללקוח\b", "לך", cleaned, flags=re.IGNORECASE)
    cleaned = auto_fix_common_hebrew_typos(cleaned)
    try:
        cleaned = apply_learned_style_rules(cleaned)
    except Exception:
        pass
    cleaned = re.sub(r"[ \t]{2,}", " ", cleaned).strip()
    return cleaned


def detect_chosen_color(text: str) -> str:
    """
    Detects when a customer selects or specifies a device color (e.g. 'שחור', 'לבן', 'אני רוצה שחור').
    Never triggers if the customer is asking 'איזה צבעים יש?'.
    """
    clean = (text or "").strip().lower()
    if not clean:
        return ""
    if any(q in clean for q in ["איזה צבע", "אילו צבע", "באיזה צבעים", "מה הצבעים", "יש צבע", "?"]):
        return ""
    colors = ["שחור", "לבן", "כחול", "אפור", "כסוף", "כסף", "זהב", "אדום", "ירוק", "סגול", "ורוד"]
    found = [c for c in colors if re.search(rf"(?:^|\s|[ב,.-]){re.escape(c)}(?:$|\s|[,.!])", clean)]
    # If the customer is stating a single chosen color (not listing both "יש שחור ויש לבן")
    if len(found) == 1:
        return found[0]
    return ""


def extract_latest_customer_question(request_text: str) -> str:
    """
    Extracts the most recent customer question from a potentially chained request_text
    (e.g. 'יש מכשיר f21 pro | שאלת המשך: איזה צבעים יש' -> 'איזה צבעים יש').
    """
    raw = (request_text or "").strip()
    if not raw:
        return ""
    parts = [p.strip() for p in raw.split("|") if p.strip()]
    latest = parts[-1] if parts else raw
    latest = re.sub(r"^(?:שאלת\s+המשך|תשובת\s+הלקוח|הודעת\s+לקוח|השגת\s+לקוח\s+על\s+המחיר)\s*:\s*", "", latest, flags=re.IGNORECASE).strip()
    return latest


def extract_kb_keywords_from_request(request_text: str) -> str:
    """
    Extracts accurate, reusable learned_kb keywords from the customer's question
    (prioritizing the latest follow-up question such as 'איזה צבעים יש' while preserving device context).
    """
    latest_q = extract_latest_customer_question(request_text).lower()
    full_q = (request_text or "").lower()
    if not latest_q:
        return ""

    # Detect if a known device model is in the full request context
    dev_tag = ""
    for model_kw in ["f21 pro", "f21p", "f21", "f22 pro", "f22p", "f22", "f25 pro", "f25p", "f25"]:
        if model_kw in full_q:
            dev_tag = model_kw.split()[0]  # e.g. f21, f22, f25
            break

    # Special high-precision keywords for color inquiries
    if any(w in latest_q for w in ["צבעים", "צבע"]):
        kws = ["איזה צבעים", "צבעים", "באיזה צבעים", "איזה צבע"]
        if dev_tag:
            kws.insert(0, f"צבעים {dev_tag}")
            kws.append(f"צבע {dev_tag}")
        return ", ".join(kws)

    # Special high-precision keywords for screen protector variety vs. specific option price
    if is_screen_protector_variety_inquiry(latest_q) or (is_screen_protector_variety_inquiry(full_q) and not detect_specific_option_name(latest_q)):
        return "מגיני מסך, מגן מסך, מגן זכוכית, מגן לאייפון, מגן לגלקסי, איזה סוגים יש, סוגי מגינים, סוגי מגנים, איזה מגן יש"

    spec_opt = detect_specific_option_name(latest_q)
    if spec_opt:
        short_opt = spec_opt.replace("מגן ", "").strip()
        return f"מחיר {spec_opt}, {spec_opt}, מחיר {short_opt}, ה{short_opt}, {short_opt}"

    filler = {
        "יש", "אין", "האם", "איזה", "איזו", "אילו", "מה", "איך", "כמה", "מתי", "אפשר", "לדעת",
        "לכם", "אצלכם", "שלכם", "לי", "לו", "זה", "הזה", "הזאת", "אני", "רוצה", "צריך", "מבקש",
        "שלום", "היי", "תודה", "בבקשה", "מכשיר", "טלפון", "פלאפון", "שאלת", "המשך"
    }
    words = [
        w for w in re.sub(r"[^\w\sא-ת0-9a-zA-Z]", " ", latest_q).split()
        if len(w) >= 3 and w not in filler
    ]
    if not words:
        words = [w for w in re.sub(r"[^\w\sא-ת0-9a-zA-Z]", " ", latest_q).split() if len(w) >= 3]

    kw_list = []
    if len(latest_q) <= 30 and len(latest_q) >= 4:
        clean_phrase = re.sub(r"[^\w\sא-ת0-9a-zA-Z]", " ", latest_q).strip()
        clean_phrase = re.sub(r"\s+", " ", clean_phrase)
        if clean_phrase:
            kw_list.append(clean_phrase)
    for w in words[:4]:
        if w not in kw_list:
            kw_list.append(w)
        if dev_tag and w != dev_tag and f"{w} {dev_tag}" not in kw_list:
            kw_list.append(f"{w} {dev_tag}")

    return ", ".join(kw_list[:5])


def extract_non_time_admin_details(admin_answer: str, request_text: str = "", recent_history: str = "") -> tuple[str, str]:
    """
    When Admin answers a multi-part customer question (e.g., "מסך עולה 400₪ אוכל להזמין ותבוא לתקן בשעה 16:00"
    or "יש ועולה 400₪ ואפשר לבוא ב 16:00"), extracts both:
    1. The adapted customer-facing answer about stock, ordering, and price (excluding the raw hour if the scheduling block formats the hour).
    2. The extracted price in NIS (e.g. "400").
    Never drops any part of Admin's answer!
    """
    raw = (admin_answer or "").strip()
    if not raw:
        return "", ""
    price_nis = extract_price_nis(raw)
    adapted_full, _ = adapt_admin_answer(raw, request_text, recent_history)

    # Convert 1st-person Admin offers ("אוכל להזמין", "אני יכול להזמין") into clear store phrasing ("נוכל להזמין עבורך")
    adapted_full = re.sub(r"\bאוכל\s+להזמין(?:\s+לך|\s+עבורך)?\b", "נוכל להזמין עבורך", adapted_full)
    adapted_full = re.sub(r"\bאני\s+יכול\s+להזמין(?:\s+לך|\s+עבורך)?\b", "נוכל להזמין עבורך", adapted_full)

    # Check if the admin answer contains non-time details (such as price, stock, screen, ordering, etc.)
    non_time_signals = [
        "₪", "שח", 'ש"ח', "שקל", "עולה", "מחיר", "עלות", "במלאי", "אין במלאי", "יש במלאי",
        "להזמין", "נזמין", "מסך", "סוללה", "שקע", "חלק", "יש לנו", "קיים"
    ]
    has_extra_info = bool(price_nis) or any(s in raw.lower() for s in non_time_signals)
    if not has_extra_info:
        return "", ""

    # Strip the trailing question / sales pitch automatically added by adapt_admin_answer if we are combining it with the scheduling question
    cleaned_info = re.sub(
        r"\s*(?:🔥\s*נשארו\s+יחידות\s+אחרונות[^\n]*|האם\s+תרצה\s+שנזמין\s+עבורך(?:\s+את\s+החלק)?\s*\??\s*😃?|—\s*האם\s+זה\s+מתאים\s+לך\?\s*😃?)\s*$",
        "",
        adapted_full
    ).strip()
    # Also strip redundant trailing time phrase if scheduling block already presents the time clearly
    cleaned_info = re.sub(r"[,.]?\s*(?:ו?(?:תבוא|תגיע|אפשר\s+לבוא|אפשר\s+להגיע|מוזמן\s+להגיע|מוזמן\s+לבוא)(?:\s+לתקן|\s+אלינו)?\s*(?:מחר\s*)?(?:בשעה|ב-|ב)\s*[0-2]?[0-9](?::[0-5][0-9])?)\s*[.!]?\s*$", "", cleaned_info).strip()
    cleaned_info = cleaned_info.rstrip(",. ")
    return cleaned_info, price_nis

def is_part_or_repair_price_inquiry(text: str, allow_with_scheduling: bool = False) -> dict:
    """
    Detects when a customer is asking about the availability or price of a repair/part
    (e.g., screen, battery, charging port) that is NOT already a fixed item in PERMANENT_LEARNED_KB (like Qin F21 screen).
    Returns a dict with average price range, part label, and device description so the bot can:
    1. Give the customer an average price range immediately.
    2. Offer to check the exact price and availability with Eran.
    """
    clean = (text or "").strip().lower()
    if not clean:
        return {"matched": False}
    if not allow_with_scheduling and is_scheduling_request(clean):
        return {"matched": False}

    # Skip if it's already a known fixed-price item in PERMANENT_LEARNED_KB (e.g. F21 screen or F21/F22/F25 purchase)
    if any(k in clean for k in ["f21", "f22", "f25"]):
        return {"matched": False}
    # Screen protectors ("מגן מסך", "מגיני מסך") are accessories with multiple types, NOT a lab screen replacement!
    if is_screen_protector_or_accessory_context(clean):
        return {"matched": False}

    is_screen = any(w in clean for w in ["מסך", "למסך", "המסך"])
    is_battery = any(w in clean for w in ["סוללה", "בטריה", "הסוללה", "הבטריה"])
    is_port = any(w in clean for w in ["שקע טעינה", "שקע", "טעינה"])

    if not (is_screen or is_battery or is_port):
        return {"matched": False}

    # Ensure it's an inquiry about availability/price/repair/ordering
    inquiry_signals = [
        "יש", "כמה", "מחיר", "עולה", "עלות", "להחליף", "החלפת", "תיקון", "לתקן",
        "להזמין", "במלאי", "נשבר", "הלך", "לא עובד", "?"
    ]
    has_device_mention = any(d in clean for d in [
        "גלקסי", "galaxy", "סמסונג", "samsung", "אייפון", "iphone", "שיאומי", "xiaomi",
        "רדמי", "redmi", "פוקו", "poco", "נוקיה", "nokia", "מכשיר", "טלפון", "פלאפון"
    ]) or bool(re.search(r"\b[aAsSmM]\d{1,2}\b", clean))

    if not (has_device_mention or any(s in clean for s in inquiry_signals)):
        return {"matched": False}

    if is_screen:
        part_name = "החלפת מסך"
        if any(w in clean for w in ["אייפון", "iphone"]):
            avg_range = "350–650 ₪"
        elif re.search(r"\b(?:a0|a1|a2|a3|m1|m2|m3|redmi|רדמי)", clean):
            avg_range = "220–320 ₪"
        elif any(w in clean for w in ["גלקסי", "galaxy", "סמסונג", "samsung"]):
            avg_range = "250–450 ₪"
        else:
            avg_range = "220–400 ₪"
    elif is_battery:
        part_name = "החלפת סוללה"
        avg_range = "150–250 ₪"
    else:
        part_name = "תיקון שקע טעינה"
        avg_range = "150–220 ₪"

    return {
        "matched": True,
        "part_name": part_name,
        "avg_range": avg_range,
    }

def is_payment_confirmation_message(text: str, type_msg: str = "") -> bool:
    """
    Detects when a customer confirms they transferred payment via Bit (or sends a payment screenshot).
    """
    clean = (text or "").strip().lower()
    if type_msg == "imageMessage" and any(w in clean for w in ["ביט", "bit", "שילמתי", "העברתי", "תשלום", "אישור", "אסמכתא", ""]):
        return True
    pay_signals = [
        "שילמתי", "העברתי", "שלחתי בביט", "העברתי בביט", "שילמתי בביט", "ביצעתי העברה",
        "בוצעה העברה", "שלחתי תשלום", "העברתי לך", "העברתי כסף", "שולם בביט", "שולם"
    ]
    return any(sig in clean for sig in pay_signals)

def is_in_progress_or_question(text: str) -> bool:
    """
    Checks if a message is an open question, diagnostic inquiry, conditional offer (e.g. ordering a part/device,
    choosing a color, or reserving last units in stock), or intermediate step expecting a customer response or action,
    where asking a closing satisfaction question is strictly premature.
    """
    if not text:
        return False
    clean = text.strip()
    
    # Check for question marks (excluding satisfaction questions themselves)
    clean_no_closing = (
        clean.replace("האם הצלחתי לעזור לך ולתת לך מענה לפנייתך", "")
        .replace("האם הצלחתי לעזור", "")
        .replace("האם אוכל לעזור לך במשהו נוסף", "")
        .replace("האם אוכל לעזור במשהו נוסף", "")
    )
    if "?" in clean_no_closing or "؟" in clean_no_closing:
        return True

    question_and_open_offer_stems = [
        "איזה", "איזו", "אילו", "מה סוג", "איזה סוג", "מה הדגם", "איזה דגם",
        "מה התקלה", "מה קורה", "מה מופיע", "מה רשום", "סוג ההגנה", "סוג הגנה",
        "כשר פליי או נטספרק", "איזה סינון", "איזה הגנה", "תוכל לבדוק",
        "תוכל לפרט", "תוכל לשלוח", "תעדכן אותי", "תעדכני אותי", "עדכן אותי",
        "עדכני אותי", "עדכן", "תעדכן", "תנסה", "תנסו", "תבדוק", "תבדקי", "נסה",
        "היכנס", "לחץ", "בצע", "הפעל", "הפעל מחדש", "התקן", "בדוק", "שישאל", "תשאל", "לשאול",
        "באיזה מכשיר", "באיזה דגם", "איך זה קרה", "ממתי", "שלח לי", "תשלח",
        "אם זה הסתדר", "אם הסתדר",
        # Open offers, color/variant selection, reservations & conditional ordering phrases
        "אם אתה רוצה", "אם תרצה", "אם את רוצה", "אם תרצי", "אם הלקוח רוצה", "אם הוא רוצה",
        "אם אתה מעוניין", "אם הלקוח מעוניין", "אם מתאים לך", "אם זה מתאים לך",
        "אפשר להזמין", "ניתן להזמין", "צריך להזמין", "תרצה שנזמין", "רוצה שנזמין",
        "נזמין לך", "נזמין עבורך", "להזמין לך", "להזמין עבורך", "תרצה שנשמור",
        "נשארו יחידות אחרונות", "תרצה שנשריין", "תרצה לשריין", "באיזה מסלול אחריות",
        "באיזה צבע", "איזה צבע", "איזה מסלול", "מה אתה מעדיף", "מה דעתך",
        "מה תרצה להזמין", "איזה מהם תרצה להזמין", "איזה מגן תרצה", "תרצה להזמין אותו", "אבדוק לך"
    ]
    if any(stem in clean for stem in question_and_open_offer_stems):
        return True

    checking_stems = [
        "אני בודק כעת", "בודק כעת", "אבדוק כעת", "אברר כעת", "נברר עבורך",
        "כבר חוזר אליך", "כבר מעדכן", "מיד חוזר", "אחזור אליך עם השלבים",
        "מברר כעת את ההנחיות"
    ]
    if any(stem in clean for stem in checking_stems):
        return True

    return False


def adapt_admin_answer(raw_answer: str, request_text: str = "", recent_history: str = "") -> tuple[str, bool]:
    """
    Holistic, system-wide Admin-to-Customer Translation, Digestion & Meta-Coaching Engine.
    Transforms ALL forms of Admin communication:
    0. Strips all Admin meta-scolding / memory / learning remarks ('כבר עניתי לו על השאלה הזאת והוא היה צריך ללמוד ממנה')
       BEFORE any pronoun replacement so meta-coaching NEVER leaks to the customer!
    1. Bot error / price corrections ('נכון המחיר שנתת ללקוח שגוי ועשית טעות של 100 שח', 'המחיר המעודכן נמוך ב 100 שח')
       -> Strips all meta-criticism, calculates relative price adjustments from history/KB, apologizes politely in 1st person,
          and presents the updated price with a strong sales close & persuasion for 'ימות המשיח ⭐'.
    2. Digests shorthand answers (e.g. 'יש שחור וישיש לבן' for 'איזה צבעים יש?') into natural, polite store Hebrew
       and automatically asks the right follow-up question to advance the sale ('באיזה צבע תרצה לבחור כדי שנשריין עבורך את המכשיר כעת?').
    3. Rewrites 3rd-person customer instructions ('אין במלאי וצריך להזמין אם הלקוח רוצה', 'תגיד לו ש...') into direct 2nd-person ('אתה', 'לך', 'עבורך').
    Returns (adapted_text, is_question_or_in_progress).
    """
    raw_str = str(raw_answer or "").strip()
    if not raw_str:
        return "", False

    combined_ctx = f"{request_text or ''} {recent_history or ''}".strip()
    latest_q = extract_latest_customer_question(request_text).lower()

    # =========================================================================
    # LAYER 0: Strip Admin Meta-Coaching / Scolding About Learning & Repetition
    # =========================================================================
    clean = strip_admin_meta_coaching(raw_str)
    if not clean:
        clean = raw_str

    # =========================================================================
    # LAYER 1: Admin Meta-Criticism & Bot Error / Relative Price Correction
    # =========================================================================
    has_bot_error_meta = bool(
        re.search(
            r"(?:נתת|רשמת|כתבת|אמרת|שלחת|מסרת)\s+(?:ללקוח|לו)|"
            r"(?:עשית\s+טעות|טעית|התבלבלת|שגוי|שגויה|טעות\s+של)|"
            r"(?:המחיר\s+(?:המעודכן\s+)?(?:נמוך|גבוה|זול|יקר)\s+ב)",
            clean,
            flags=re.IGNORECASE
        )
    )

    m_rel_delta = re.search(
        r'(?:טעות\s+של|נמוך\s+ב-?|פחות\s+|זול\s+ב-?|הורדתי\s+|להוריד\s+|גבוה\s+ב-?|יקר\s+ב-?)\s*(\d{2,3})\s*(?:₪|ש"ח|ש\'\'ח|שח|שקלים|שקל)?',
        clean,
        flags=re.IGNORECASE
    )
    rel_delta = int(m_rel_delta.group(1)) if m_rel_delta else 0
    is_delta_add = bool(
        rel_delta
        and re.search(r"המחיר\s+המעודכן\s+(?:גבוה|יקר)\s+ב", clean)
        and not re.search(r"(?:שנתת|שרשמת|שכתבת|שאמרת)\s+(?:ללקוח\s+|לו\s+)?(?:הוא\s+)?(?:גבוה|יקר)", clean)
    )

    if has_bot_error_meta:
        clean_without_delta = re.sub(
            r'(?:טעות\s+של|נמוך\s+ב-?|פחות\s+|זול\s+ב-?|הורדתי\s+|להוריד\s+|גבוה\s+ב-?|יקר\s+ב-?)\s*\d{2,3}\s*(?:₪|ש"ח|ש\'\'ח|שח|שקלים|שקל)?',
            " ",
            clean,
            flags=re.IGNORECASE
        )
        explicit_prices_in_admin = [
            int(m.group(1)) for m in re.finditer(r"\b(\d{3,4})\b", clean_without_delta)
            if 100 <= int(m.group(1)) <= 6000
        ]

        kosher_info = extract_kosher_device_track_prices(request_text, recent_history)
        if kosher_info.get("matched"):
            dev_label = kosher_info["device_label"]
            if len(explicit_prices_in_admin) >= 2:
                p_low = min(explicit_prices_in_admin[0], explicit_prices_in_admin[1])
                p_high = max(explicit_prices_in_admin[0], explicit_prices_in_admin[1])
            elif len(explicit_prices_in_admin) == 1:
                p_low = explicit_prices_in_admin[0]
                p_high = p_low + 100
            elif rel_delta > 0:
                hist_galut_all = re.findall(r"גלות[^\n0-9]{0,45}(\d{3,4})", combined_ctx)
                hist_yemot_all = re.findall(r"ימות\s+המשיח[^\n0-9]{0,80}(\d{3,4})", combined_ctx)
                if hist_galut_all and hist_yemot_all:
                    old_g = int(hist_galut_all[-1])
                    old_y = int(hist_yemot_all[-1])
                    p_low = (old_g + rel_delta) if is_delta_add else (old_g - rel_delta)
                    p_high = (old_y + rel_delta) if is_delta_add else (old_y - rel_delta)
                else:
                    p_low = int(kosher_info["galut_price"])
                    p_high = int(kosher_info["yemot_price"])
            else:
                p_low = int(kosher_info["galut_price"])
                p_high = int(kosher_info["yemot_price"])

            corrected_msg = (
                f"סליחה על הבלבול מקודם! בדקתי שוב מול ערן והמחיר המעודכן והמדויק עבור {dev_label} הוא: 📱\n"
                f"• מסלול גלות (אחריות יבואן רשמי בלבד): {p_low} ₪\n"
                f"• ⭐ מסלול ימות המשיח (המסלול המומלץ והמשתלם ביותר שלנו!): {p_high} ₪ — בתוספת קטנה אתה מקבל שקט נפשי מלא עם תיקון אקספרס במעבדה שלנו בחדרה תוך שעתיים (במקום להמתין 3 שבועות ליבואן!), מכשיר חלופי חינם, העברת נתונים ועדכוני גרסה ללא עלות!\n\n"
                f"🔥 נשארו יחידות אחרונות במלאי! תרצה שנשריין עבורך מכשיר כעת כדי שלא תיתקע בלי? באיזה מסלול אחריות תרצה לבחור (ימות המשיח ⭐ המומלץ או גלות)? 😃"
            )
            return corrected_msg, True

        if explicit_prices_in_admin:
            new_p = explicit_prices_in_admin[0]
            if is_repair_or_smartphone_context(combined_ctx):
                return (
                    f"סליחה על הבלבול מקודם! בדקתי שוב מול ערן והמחיר המעודכן והמדויק עבורך הוא *{new_p} ₪*. 🛠️\n"
                    f"האם תרצה שנזמין ונשריין עבורך כעת? 😃"
                ), True
            return (
                f"סליחה על הבלבול מקודם! בדקתי שוב מול ערן והמחיר המעודכן והמדויק עבורך הוא *{new_p} ₪*. 📱\n"
                f"🔥 נשארו יחידות אחרונות במלאי! תרצה שנשריין עבורך כעת כדי שלא תיתקע בלי? 😃"
            ), True

        if rel_delta > 0:
            prev_p_str = extract_price_nis(combined_ctx)
            if prev_p_str and int(prev_p_str) > rel_delta:
                old_p = int(prev_p_str)
                new_p = (old_p + rel_delta) if is_delta_add else (old_p - rel_delta)
                if is_repair_or_smartphone_context(combined_ctx):
                    return (
                        f"סליחה על הבלבול מקודם! בדקתי שוב מול ערן והמחיר המעודכן והמדויק עבורך הוא *{new_p} ₪*. 🛠️\n"
                        f"האם תרצה שנזמין ונשריין עבורך כעת? 😃"
                    ), True
                return (
                    f"סליחה על הבלבול מקודם! בדקתי שוב מול ערן והמחיר המעודכן והמדויק עבורך הוא *{new_p} ₪*. 📱\n"
                    f"🔥 נשארו יחידות אחרונות במלאי! תרצה שנשריין עבורך כעת כדי שלא תיתקע בלי? 😃"
                ), True

        clean = sanitize_admin_leakage(clean)

    # =========================================================================
    # LAYER 1.5: Digesting Color / Variant Inquiries & Asking Customer to Choose!
    # =========================================================================
    color_vocab = ["שחור", "לבן", "כחול", "אפור", "כסוף", "כסף", "זהב", "אדום", "ירוק", "סגול", "ורוד"]
    mentioned_colors = [c for c in color_vocab if re.search(rf"(?:^|\s|[ו,.-]){re.escape(c)}(?:$|\s|[,.!])", clean)]
    is_color_inquiry = any(w in latest_q for w in ["צבע", "צבעים"]) or (len(mentioned_colors) >= 1 and any(w in combined_ctx.lower() for w in ["צבע", "צבעים"]))

    if is_color_inquiry and mentioned_colors:
        kosher_dev = extract_kosher_device_track_prices(request_text, recent_history)
        dev_name_str = f"המכשיר ({kosher_dev['device_label']})" if kosher_dev.get("matched") and kosher_dev["device_label"] != "המכשיר" else "המכשיר"
        if len(mentioned_colors) == 1:
            color_sentence = f"{dev_name_str} קיים אצלנו במלאי בצבע *{mentioned_colors[0]}*. 🎨📱"
            ask_color = f"האם תרצה שנשריין עבורך את המכשיר בצבע {mentioned_colors[0]} כעת? 😃"
        elif len(mentioned_colors) == 2:
            color_sentence = f"{dev_name_str} קיים אצלנו במלאי בצבע *{mentioned_colors[0]}* ובצבע *{mentioned_colors[1]}*. 🎨📱"
            ask_color = f"באיזה צבע תרצה לבחור ({mentioned_colors[0]} או {mentioned_colors[1]}) כדי שנשריין עבורך את המכשיר כעת? 😃"
        else:
            colors_str = ", ".join(mentioned_colors[:-1]) + f" ו{mentioned_colors[-1]}"
            color_sentence = f"{dev_name_str} קיים אצלנו במלאי בצבעים: *{colors_str}*. 🎨📱"
            ask_color = "באיזה צבע תרצה לבחור כדי שנשריין עבורך את המכשיר כעת? 😃"
        return f"{color_sentence}\n{ask_color}", True

    # =========================================================================
    # LAYER 2: Specific Diagnostic & Instruction Templates
    # =========================================================================
    if re.search(r"(?:שישאל|תשאל|לשאול)\s+(?:את\s+הלקוח\s+|אותו\s+)?מה\s+סוג\s+ההגנה", clean, re.IGNORECASE):
        return "כדי שנוכל לעזור לך לסדר את המכשיר מרחוק, מה סוג ההגנה שמותקן עליו כרגע? (למשל: כשר פליי / נטספרק / אחר)", True

    if re.search(r"(?:שישאל|תשאל|לשאול)\s+(?:את\s+הלקוח\s+|אותו\s+)?איזה\s+(?:סוג\s+)?הגנה", clean, re.IGNORECASE):
        return "כדי שנוכל לעזור לך לסדר את המכשיר מרחוק, איזה סוג הגנה יש לך על המכשיר? (כשר פליי / נטספרק / אחר)", True

    if re.search(r"(?:שישאל|תשאל|לשאול)\s+(?:את\s+הלקוח\s+|אותו\s+)?(?:מה\s+)?איזה\s+דגם", clean, re.IGNORECASE):
        return "באיזה דגם מכשיר מדובר בדיוק?", True

    clean = re.sub(
        r"^(?:תתנצל\s+(?:בפניו\s+|בפני\s+הלקוח\s+)?ו?)?(?:תגיד|תאמר|תמסור|תכתוב|תרשום|תעדכן|תענה|תשיב|תסביר|תציע|תמליץ)\s+(?:לו|לה|ללקוח|אותו|את\s+הלקוח|עבורו)\s*(?:ש-|ש|:)?\s*",
        "",
        clean,
        flags=re.IGNORECASE
    ).strip()

    m_ask = re.match(r"^(?:שישאל|תשאל|לשאול|תברר|שנברר)\s+(?:אותו\s+|את\s+הלקוח\s+|איתו\s+|מול\s+הלקוח\s+)?(?:אם\s+|האם\s+)?(.+)$", clean)
    if m_ask:
        is_if = bool(re.match(r"^(?:שישאל|תשאל|לשאול|תברר|שנברר)\s+(?:אותו\s+|את\s+הלקוח\s+|איתו\s+|מול\s+הלקוח\s+)?(?:אם|האם)\s+", clean))
        content = m_ask.group(1).strip()
        content = re.sub(r"\bהלקוח\s+רוצה\b", "אתה רוצה", content)
        content = re.sub(r"\bהלקוח\s+מעוניין\b", "אתה מעוניין", content)
        content = re.sub(r"\bהלקוח\s+בוחר\b", "אתה בוחר", content)
        content = re.sub(r"\bהוא\s+רוצה\b", "אתה רוצה", content)
        content = re.sub(r"\bהוא\s+מעוניין\b", "אתה מעוניין", content)
        content = re.sub(r"\bהוא\s+בוחר\b", "אתה בוחר", content)
        content = re.sub(r"\bלו\b", "לך", content)
        content = re.sub(r"\bשלו\b", "שלך", content)
        content = re.sub(r"\bאותו\b", "אותך", content)
        content = re.sub(r"\bאיתו\b", "איתך", content)
        content = re.sub(r"\bהוא\b", "אתה", content)
        if is_if and not content.startswith(("האם", "אם")):
            content = f"האם {content}"
        if not content.endswith("?"):
            content += "?"
        return sanitize_admin_leakage(content), True

    m_step = re.match(r"^(?:שיכנס|שילחץ|שיבצע|שיוריד|שיעדכן|שיפעיל)\s+(.+)$", clean)
    if m_step:
        verb = clean.split()[0]
        rest = clean[len(verb):].strip()
        verb_map = {
            "שיכנס": "היכנס",
            "שילחץ": "לחץ",
            "שיבצע": "בצע",
            "שיוריד": "הורד",
            "שיעדכן": "עדכן",
            "שיפעיל": "הפעל"
        }
        direct_verb = verb_map.get(verb, verb)
        rest = re.sub(r"\bלו\b", "לך", rest)
        rest = re.sub(r"\bשלו\b", "שלך", rest)
        adapted = f"{direct_verb} {rest}\nעדכן אותי בבקשה אם זה הסתדר לך."
        return sanitize_admin_leakage(adapted), True

    # =========================================================================
    # LAYER 3: Comprehensive 3rd-Person & 2nd-Person-Bot -> Customer Speech
    # =========================================================================
    adapted = strip_admin_meta_coaching(clean)

    adapted = re.sub(r"\bוצריך\s+להזמין\b", "ואפשר להזמין", adapted)
    adapted = re.sub(r"\bצריך\s+להזמין\b", "אפשר להזמין", adapted)
    adapted = re.sub(r"\bאוכל\s+להזמין(?:\s+לך|\s+עבורך|\s+ללקוח|\s+לו)?\b", "נוכל להזמין עבורך", adapted)
    adapted = re.sub(r"\bאני\s+יכול\s+להזמין(?:\s+לך|\s+עבורך|\s+ללקוח|\s+לו)?\b", "נוכל להזמין עבורך", adapted)

    replacements = [
        (r"\bו?(?:תגיד|תאמר|תמסור|תכתוב|תרשום|תעדכן|תסביר)\s+(?:לו|לה|ללקוח|אותו|את\s+הלקוח)\s*(?:ש-|ש|:)?\s*", ""),
        (r"\bו?(?:תשאל|שישאל|תברר)\s+(?:אותו|את\s+הלקוח|איתו)\s+", "ו"),
        (r"\b(?:שנתת|שרשמת|שכתבת|שאמרת|ששלחת)\s+(?:ללקוח|לו)\b", "שנמסר קודם"),
        (r"\b(?:נתת|רשמת|כתבת|אמרת|שלחת)\s+(?:ללקוח|לו)\b", "נמסר קודם"),
        (r"אם\s+הלקוח\s+רוצה", "אם אתה רוצה"),
        (r"אם\s+הוא\s+רוצה", "אם אתה רוצה"),
        (r"אם\s+הלקוח\s+ירצה", "אם תרצה"),
        (r"אם\s+הוא\s+ירצה", "אם תרצה"),
        (r"אם\s+הלקוח\s+מעוניין", "אם אתה מעוניין"),
        (r"אם\s+הוא\s+מעוניין", "אם אתה מעוניין"),
        (r"אם\s+הלקוח\s+בוחר", "אם אתה בוחר"),
        (r"אם\s+הוא\s+בוחר", "אם אתה בוחר"),
        (r"במה\s+הלקוח\s+בוחר", "במה אתה בוחר"),
        (r"במה\s+הוא\s+בוחר", "במה אתה בוחר"),
        (r"איזה\s+מסלול\s+הלקוח\s+רוצה", "איזה מסלול אתה רוצה"),
        (r"איזה\s+מסלול\s+הוא\s+רוצה", "איזה מסלול אתה רוצה"),
        (r"אם\s+(?:זה\s+)?מתאים\s+ללקוח", "אם זה מתאים לך"),
        (r"אם\s+(?:זה\s+)?מתאים\s+לו", "אם זה מתאים לך"),
        (r"אם\s+נוח\s+ללקוח", "אם נוח לך"),
        (r"אם\s+נוח\s+לו", "אם נוח לך"),
        (r"עבור\s+הלקוח", "עבורך"),
        (r"בשביל\s+הלקוח", "בשבילך"),
        (r"מול\s+הלקוח", "איתך"),
        (r"\bעבורו\b", "עבורך"),
        (r"\bבשבילו\b", "בשבילך"),
        (r"להזמין\s+ללקוח", "להזמין לך"),
        (r"להזמין\s+לו\b", "להזמין לך"),
        (r"לשריין\s+ללקוח", "לשריין לך"),
        (r"לשריין\s+לו\b", "לשריין לך"),
        (r"לסדר\s+ללקוח", "לסדר לך"),
        (r"לסדר\s+לו\b", "לסדר לך"),
        (r"לבדוק\s+ללקוח", "לבדוק לך"),
        (r"לבדוק\s+לו\b", "לבדוק לך"),
        (r"לשמור\s+ללקוח", "לשמור לך"),
        (r"לשמור\s+לו\b", "לשמור לך"),
        (r"המכשיר\s+של\s+הלקוח", "המכשיר שלך"),
        (r"הטלפון\s+של\s+הלקוח", "הטלפון שלך"),
        (r"הפלאפון\s+של\s+הלקוח", "הפלאפון שלך"),
        (r"\bהמכשיר\s+שלו\b", "המכשיר שלך"),
        (r"\bהטלפון\s+שלו\b", "הטלפון שלך"),
        (r"\bהפלאפון\s+שלו\b", "הפלאפון שלך"),
        (r"\bהמסך\s+שלו\b", "המסך שלך"),
        (r"שיש\s+ללקוח", "שיש לך"),
        (r"\bשיש\s+לו\b", "שיש לך"),
        (r"\bשל\s+הלקוח\b", "שלך"),
        (r"\bאת\s+הלקוח\b", "אותך"),
        (r"\bללקוח\b", "לך"),
        (r"\bהלקוח\s+יכול\b", "אתה יכול"),
        (r"\bהלקוח\s+מוזמן\b", "אתה מוזמן"),
        (r"\bהלקוח\s+צריך\b", "עליך"),
        (r"\bשירשום\b", "תרשום לנו"),
        (r"\bשיכתוב\b", "תכתוב לנו"),
        (r"\bשיעדכן\b", "תעדכן אותנו"),
        (r"\bשישלח\b", "שלח לנו"),
        (r"\bשישלם\b", "תוכל לשלם"),
        (r"\bשיעביר\b", "תוכל להעביר"),
        (r"\bשיבחר\b", "תבחר"),
        (r"\bשישריין\b", "תשריין"),
        (r"\bשיביא\b", "אתה מוזמן להביא"),
        (r"\bשיגיע\b", "אתה מוזמן להגיע"),
        (r"\bשיבוא\b", "אתה מוזמן להגיע"),
    ]
    for pat, repl in replacements:
        adapted = re.sub(pat, repl, adapted, flags=re.IGNORECASE)

    adapted = sanitize_admin_leakage(adapted)

    adapted = re.sub(r"^אין\s+במלאי\s+ואפשר\s+להזמין", "כרגע אין במלאי, אך אפשר להזמין", adapted)
    adapted = re.sub(r"^אין\s+במלאי\s+אפשר\s+להזמין", "כרגע אין במלאי, אפשר להזמין", adapted)

    # =========================================================================
    # LAYER 4: Automatic Sales Closing, Option Choice, Comparison & Reservation CTA
    # =========================================================================
    detected_price = extract_price_nis(adapted)
    req_part_info = is_part_or_repair_price_inquiry(request_text)

    # Check if customer asked about ONE specific option/item (e.g. "מה מחיר מגן הפיברגלס" or "[TARGET_ITEM:מגן פיברגלס]")
    m_target_tags = re.findall(r"\[TARGET_ITEM:([^\]]+)\]", request_text or "")
    specific_req_option = (
        (m_target_tags[-1].strip() if m_target_tags else "")
        or detect_specific_option_name(latest_q)
        or detect_specific_option_name(adapted)
    )

    if re.fullmatch(r"\d{2,4}", adapted.strip()) and detected_price:
        if specific_req_option:
            adapted = f"המחיר של *{specific_req_option}* הוא *{detected_price} ₪*"
        else:
            adapted = f"המחיר המדויק הוא *{detected_price} ₪*"
    elif detected_price and "₪" not in adapted and "שח" not in adapted and 'ש"ח' not in adapted and "שקל" not in adapted:
        adapted = re.sub(rf"\b{re.escape(detected_price)}\b", f"{detected_price} ₪", adapted, count=1)
        if specific_req_option and specific_req_option not in adapted and len(adapted.split()) <= 4:
            adapted = f"המחיר של *{specific_req_option}* הוא *{detected_price} ₪*"

    is_order_offer = any(w in adapted for w in ["אפשר להזמין", "ניתן להזמין", "להזמין לך", "להזמין עבורך", "נזמין לך", "נוכל להזמין"])
    is_conditional_choice = any(w in adapted for w in ["אם אתה רוצה", "אם תרצה", "אם אתה מעוניין", "אם זה מתאים לך", "אם נוח לך"])

    extracted_opts = extract_options_and_prices_from_text(adapted)
    is_multi_option_list = len(extracted_opts) >= 2 or (
        is_screen_protector_or_accessory_context(combined_ctx + " " + adapted)
        and not specific_req_option
        and not detected_price
    )
    is_single_specific_option_price = bool(
        detected_price and len(extracted_opts) < 2 and (
            bool(specific_req_option)
            or is_screen_protector_or_accessory_context(combined_ctx + " " + adapted)
        )
    )

    is_price_approval_for_part = bool(
        detected_price and not is_multi_option_list and not is_single_specific_option_price and (
            req_part_info.get("matched")
            or is_repair_or_smartphone_context(combined_ctx)
            or any(w in (request_text or "") for w in ["מסך", "סוללה", "שקע", "חלק", "להזמין", "מחיר מדויק", "בדיקת מחיר"])
        )
    )
    is_device_price_quote = bool(
        detected_price and not is_price_approval_for_part and not is_multi_option_list
        and not is_single_specific_option_price and not is_scheduling_request(request_text)
    )
    kosher_context_check = extract_kosher_device_track_prices(f"{adapted} {request_text}", recent_history)
    is_in_active_device_sale = bool(
        kosher_context_check.get("matched")
        and not is_repair_or_smartphone_context(request_text)
        and not is_multi_option_list
        and not is_single_specific_option_price
    )

    if is_device_price_quote and "?" not in adapted:
        if is_in_active_device_sale or any(w in combined_ctx.lower() for w in ["כשר", "f21", "f22", "f25", "qin", "גלות", "ימות המשיח"]):
            adapted = (
                adapted.rstrip(".!, ")
                + "\n\n⭐ *המלצה חמה:* אנו ממליצים לבחור ב*מסלול ימות המשיח* שמעניק אחריות מעבדה מלאה אצלנו בחדרה, תיקון אקספרס תוך שעתיים ומכשיר חלופי חינם!\n"
                + "🔥 נשארו יחידות אחרונות במלאי! תרצה שנשריין עבורך מכשיר כעת כדי שלא תיתקע בלי? באיזה מסלול אחריות תרצה לבחור? 😃"
            )
        else:
            adapted = (
                adapted.rstrip(".!, ")
                + ".\n🔥 נשארו יחידות אחרונות במלאי! תרצה שנשריין עבורך מכשיר כעת כדי שלא תיתקע בלי? 😃"
            )
        is_order_offer = True
    elif is_single_specific_option_price and "?" not in adapted:
        # Check if a DIFFERENT option price was already quoted earlier in this conversation (Comparison context!)
        prev_q_item, prev_q_price = "", ""
        m_prev_lq = re.findall(r"\[LAST_QUOTED_ITEM:([^\]]+)\]\s*\[LAST_QUOTED_PRICE:(\d{2,4})\]", f"{request_text or ''} {recent_history or ''}")
        if m_prev_lq:
            for p_it, p_pr in reversed(m_prev_lq):
                if p_it.strip() != specific_req_option:
                    prev_q_item, prev_q_price = p_it.strip(), p_pr.strip()
                    break
        if not prev_q_item and recent_history:
            for opt_h in extract_options_and_prices_from_text(recent_history):
                if opt_h.get("name") and opt_h.get("price") and opt_h["name"] != specific_req_option:
                    prev_q_item, prev_q_price = opt_h["name"], opt_h["price"]
                    break

        if prev_q_item and prev_q_price and specific_req_option:
            adapted = (
                adapted.rstrip(".!, ")
                + f" (לעומת *{prev_q_item}* שמחירו *{prev_q_price} ₪*). 🛡️✨\n"
                + f"תרצה להזמין אותו כעת, או שאתה מעדיף את ה*{prev_q_item}*?\n"
                + f"לצורך הזמנה ושריון מיד, ניתן להעביר את הסכום של המגן שתבחר בביט (Bit) למספר *{BIT_PAYMENT_PHONE}* (ערן נקר - נעם שיח) ולשלוח לנו כאן עדכון! 😃"
            )
        else:
            adapted = (
                adapted.rstrip(".!, ")
                + ". 🛡️✨\n"
                + "תרצה להזמין אותו כעת?\n"
                + f"לצורך הזמנה ושריון מיד, ניתן להעביר כעת *{detected_price} ₪* בביט (Bit) למספר *{BIT_PAYMENT_PHONE}* (ערן נקר - נעם שיח) ולשלוח לנו כאן עדכון! 😃"
            )
        is_order_offer = True
    elif is_multi_option_list and not is_order_offer and "?" not in adapted:
        adapted = adapted.rstrip(".!, ") + ".\nמה תרצה להזמין? 😃"
        is_order_offer = True
    elif is_price_approval_for_part and not is_order_offer and "?" not in adapted:
        adapted = (
            adapted.rstrip(".!, ")
            + ". 🛠️\nתרצה להזמין אותו כעת?"
        )
        is_order_offer = True
    elif (is_order_offer or is_conditional_choice) and "?" not in adapted:
        if is_order_offer and is_multi_option_list:
            adapted = adapted.rstrip(".!, ") + ".\nמה תרצה להזמין? 😃"
        elif is_order_offer:
            adapted = adapted.rstrip(".!, ") + ".\nתרצה להזמין אותו כעת? 😃"
        else:
            adapted = adapted.rstrip(".!, ") + " — האם זה מתאים לך? 😃"
    elif is_in_active_device_sale and "?" not in adapted and not is_scheduling_request(request_text):
        # Customer asked a follow-up question during an active device sale (e.g. specs, features, options) -> Answer and drive toward closing the sale!
        if any(q in latest_q for q in ["איזה", "איזו", "אילו"]):
            adapted = adapted.rstrip(".!, ") + ".\nבאיזו אפשרות תרצה לבחור כדי שנשריין עבורך את המכשיר כעת? 😃"
        else:
            adapted = (
                adapted.rstrip(".!, ")
                + ".\nתרצה שנשריין עבורך את המכשיר כעת? באיזה מסלול אחריות תרצה לבחור (ימות המשיח ⭐ המומלץ או גלות)? 😃"
            )
        is_order_offer = True

    try:
        adapted = apply_learned_style_rules(adapted)
    except Exception:
        pass
    is_q = is_in_progress_or_question(adapted) or is_order_offer or is_conditional_choice or is_price_approval_for_part or is_device_price_quote or is_in_active_device_sale or is_multi_option_list or is_single_specific_option_price
    return adapted, is_q


def format_admin_answer_for_customer(target_phone: str, admin_answer: str, request_text: str = "", customer_name: str = "", msg_count: int = 2, recent_history: str = "") -> str:
    # Reduce name usage: only at the very start of conversation
    name_str = f" {customer_name}" if (customer_name and customer_name not in COMMON_NON_NAMES and msg_count <= 1) else ""
    
    # Generic accurate lead-in: "חזרתי אליך בנוגע לפנייתך"
    lead_in = f"שלום{name_str}, חזרתי אליך בנוגע לפנייתך:" if name_str else "חזרתי אליך בנוגע לפנייתך:"

    adapted_ans, is_in_prog = adapt_admin_answer(admin_answer, request_text, recent_history)

    if adapted_ans.startswith(("שלום", "היי", "הי", "סליחה על הבלבול")):
        reply = adapted_ans
    else:
        reply = f"{lead_in}\n{adapted_ans}"

    # Strictly do NOT append satisfaction question if the message is in progress, quoting a price/sale, asking a question, or awaiting customer decision!
    if not is_in_prog and not is_in_progress_or_question(reply):
        closing_q = "האם הצלחתי לעזור לך ולתת לך מענה לפנייתך? 😃"
        if not any(q in reply for q in ["האם הצלחתי לעזור", "מענה לפנייתך", "לעזור לך", "במשהו נוסף", "נשארו יחידות אחרונות", "תרצה שנשריין", "באיזה צבע"]):
            reply = f"{reply.rstrip()}\n\n{closing_q}"

    return sanitize_admin_leakage(reply)

def is_pure_greeting(text: str) -> bool:
    clean = re.sub(r"[^\w\sא-תa-zA-Z]", " ", text or "").strip().lower()
    words = clean.split()
    if not words:
        return False
    greeting_stems = {
        "שלום", "היי", "הי", "אהלן", "בוקר", "ערב", "צהריים", "לילה", "טוב", "טובה",
        "טובים", "שלוםם", "היוש", "הייוש", "הלו", "hello", "hi", "hey", "ברכה", "נעים",
        "מה", "נשמע", "שלומך", "קורה", "העניינים", "איתך"
    }
    for w in words:
        stem = w[1:] if (w.startswith("ו") and len(w) > 2 and w not in greeting_stems) else w
        if stem not in greeting_stems and w not in greeting_stems:
            return False
    return True

