STORE_NAME = "נעם שיח (נעם שיח תקשורת)"
STORE_OWNER_NAME = "ערן נקר"
STORE_OWNER_SHORT = "ערן"

def is_store_owner_question(text: str) -> bool:
    clean = re.sub(r"[^\w\sא-ת]", " ", text or "").strip().lower()
