def format_pos_item_answer(item: dict, all_sale_prices: list[int] | None = None) -> str:
    """
    Formats a live POS inventory record into a customer WhatsApp response:
    - Exposes ONLY the Customer Sale Price (NEVER cost price, supplier/importer names, or internal counts).
    - Presents the price as an Estimated Price (מחיר משוערך) across importers (e.g. 'סביב 380–420 ₪' or 'סביב 390 ₪').
    - States clearly that the agent is checking physical stock availability in the store right now.
    """
    name = item.get("product_name") or "המוצר"
    cat = (item.get("category") or "").lower()
    galut_p = item.get("price_galut")
    yemot_p = item.get("price_yemot")
    single_p = item.get("single_price")
    colors = (item.get("colors") or "").strip()

    prices = sorted(set(int(p) for p in (all_sale_prices or []) if p and int(p) > 0))
    if not prices:
        for p_cand in (single_p, galut_p, yemot_p):
            if p_cand and int(p_cand) > 0:
                prices.append(int(p_cand))
        prices = sorted(set(prices))

    if not prices:
        return ""

    if len(prices) >= 2 and not (galut_p and yemot_p):
        est_price_str = f"{prices[0]}–{prices[-1]} ₪"
    else:
        est_price_str = f"{prices[0]} ₪"

    color_line = f"\n🎨 *צבעים שמופיעים במערכת:* {colors}" if colors else ""
    if galut_p and yemot_p and ("כשר" in cat or "מכשיר" in cat or not is_repair_or_smartphone_context(name)):
        return (
            f"המחיר המשוערך עבור מכשיר *{name}* אצלנו הוא: 📱{color_line}\n"
            f"• מסלול גלות (אחריות יבואן רשמי): סביב *{galut_p} ₪*\n"
            f"• ⭐ מסלול ימות המשיח (אחריות מעבדה מקומית בחדרה — המומלץ!): סביב *{yemot_p} ₪*\n\n"
            f"אני בודק כעת מול ערן שהמכשיר אכן זמין במלאי הפיזי בחנות ומה המחיר הסופי עבורך, וכבר חוזר אליך עם תשובה מדויקת! 😃"
        )

    icon = "🛠️" if (is_repair_or_smartphone_context(name) or "תיקון" in cat or "מעבדה" in cat or "חלק" in cat) else "📱"
    return (
        f"המחיר המשוערך עבור *{name}* הוא סביב *{est_price_str}* (בהתאם ליבואן ולדגם שבמלאי). {icon}{color_line}\n"
        f"אני בודק כעת מול ערן שהפריט אכן קיים במלאי הפיזי בחנות ומה המחיר המדויק עבורך, וכבר חוזר אליך! 😃"
    )

def _parse_aspnet_form_inputs(html_text: str) -> dict:
    """
    Parses an ASP.NET WebForms HTML page (such as https://cellular.neworder.co.il/heb/login.aspx)
    to extract all <input>, <button>, and __doPostBack login fields:
    - hidden fields (__VIEWSTATE, __VIEWSTATEGENERATOR, __EVENTVALIDATION)
    - 3 login fields: company input(s) (שם חברה), username input(s) (שם משתמש), password input(s) (סיסמה)
    - checkbox inputs (e.g., simple 'אני לא רובוט' / 'זכור אותי' checkboxes) -> automatically checked ('on')
    - Google reCAPTCHA / Turnstile detection (has_recaptcha)
    - submit buttons, image buttons (.x/.y), and __doPostBack link targets
    """
    hidden_fields = {}
    company_inputs = []
    user_inputs = []
    other_text_inputs = []
    password_inputs = []
    checkbox_inputs = []
    submit_inputs = []
    image_submit_inputs = []
    postback_targets = []

    company_keywords = ["comp", "firm", "business", "client", "account", "branch", "store", "org", "חברה", "עסק", "סניף", "לקוח", "קוד"]
    user_keywords = ["user", "login", "uname", "emp", "worker", "agent", "משתמש", "עובד"]

    html_low = (html_text or "").lower()
    has_recaptcha = any(
        w in html_low
        for w in ["g-recaptcha", "grecaptcha", "recaptcha/api.js", "h-captcha", "cf-turnstile"]
    )

    for m_inp in re.finditer(r"<input\b([^>]+)>", html_text or "", flags=re.IGNORECASE):
        attrs_raw = m_inp.group(1)
        m_name = re.search(r"\bname\s*=\s*[\x22\x27]([^\x22\x27]+)[\x22\x27]", attrs_raw, re.IGNORECASE)
        if not m_name:
            continue
        inp_name = m_name.group(1).strip()
        m_id = re.search(r"\bid\s*=\s*[\x22\x27]([^\x22\x27]+)[\x22\x27]", attrs_raw, re.IGNORECASE)
        inp_id = m_id.group(1).strip() if m_id else ""
        m_ph = re.search(r"\b(?:placeholder|title|aria-label)\s*=\s*[\x22\x27]([^\x22\x27]+)[\x22\x27]", attrs_raw, re.IGNORECASE)
        inp_ph = m_ph.group(1).strip() if m_ph else ""
        m_type = re.search(r"\btype\s*=\s*[\x22\x27]([^\x22\x27]+)[\x22\x27]", attrs_raw, re.IGNORECASE)
        inp_type = (m_type.group(1).strip().lower() if m_type else "text")
        m_val = re.search(r"\bvalue\s*=\s*[\x22\x27]([^\x22\x27]*)[\x22\x27]", attrs_raw, re.IGNORECASE)
        inp_val = m_val.group(1) if m_val else ""

        combined_meta = f"{inp_name} {inp_id} {inp_ph}".lower()

        if inp_type == "hidden" or inp_name.startswith("__"):
            hidden_fields[inp_name] = inp_val
        elif inp_type == "checkbox":
            checkbox_inputs.append((inp_name, inp_val or "on"))
        elif inp_type == "password" or any(k in combined_meta for k in ["pass", "pwd", "סיסמ"]):
            password_inputs.append(inp_name)
        elif inp_type == "image":
            image_submit_inputs.append(inp_name)
            submit_inputs.append((inp_name, inp_val))
        elif inp_type in ("submit", "button") or any(k in inp_name.lower() for k in ["btn", "submit", "cmdlogin", "loginbutton"]):
            submit_inputs.append((inp_name, inp_val))
        elif inp_type in ("text", "email", "tel", "number"):
            if any(k in combined_meta for k in company_keywords):
                company_inputs.append(inp_name)
            elif any(k in combined_meta for k in user_keywords):
                user_inputs.append(inp_name)
            else:
                other_text_inputs.append(inp_name)

    # Also check <button> elements
    for m_btn in re.finditer(r"<button\b([^>]*)>(.*?)</button>", html_text or "", flags=re.IGNORECASE | re.DOTALL):
        b_attrs, b_inner = m_btn.group(1), m_btn.group(2)
        m_bname = re.search(r"\bname\s*=\s*[\x22\x27]([^\x22\x27]+)[\x22\x27]", b_attrs, re.IGNORECASE)
        if m_bname:
            b_val_m = re.search(r"\bvalue\s*=\s*[\x22\x27]([^\x22\x27]*)[\x22\x27]", b_attrs, re.IGNORECASE)
            b_txt = re.sub(r"<[^>]+>", "", b_inner).strip()
            submit_inputs.append((m_bname.group(1).strip(), b_val_m.group(1) if b_val_m else (b_txt or "כניסה")))

    # Also extract ASP.NET __doPostBack('target', 'arg') login triggers
    for m_pb in re.finditer(r"__doPostBack\s*\(\s*[\x22\x27]([^\x22\x27]+)[\x22\x27]\s*,\s*[\x22\x27]([^\x22\x27]*)[\x22\x27]\s*\)", html_text or "", flags=re.IGNORECASE):
        pb_target, pb_arg = m_pb.group(1).strip(), m_pb.group(2).strip()
        if any(k in pb_target.lower() for k in ["login", "btn", "submit", "cmd", "enter", "ok"]):
            postback_targets.insert(0, (pb_target, pb_arg))
        else:
            postback_targets.append((pb_target, pb_arg))

    # Smart positional resolution for NewOrder's 3-field login form (שם חברה + שם משתמש + סיסמה)
    if other_text_inputs:
        if not company_inputs and not user_inputs:
            if len(other_text_inputs) >= 2:
                company_inputs.append(other_text_inputs[0])
                user_inputs.extend(other_text_inputs[1:])
            else:
                user_inputs.extend(other_text_inputs)
        elif company_inputs and not user_inputs:
            user_inputs.extend(other_text_inputs)
        elif user_inputs and not company_inputs:
            company_inputs.extend(other_text_inputs)

    all_text_inputs = company_inputs + [u for u in user_inputs if u not in company_inputs]
    return {
        "hidden_fields": hidden_fields,
        "company_inputs": company_inputs,
        "user_inputs": user_inputs,
        "text_inputs": all_text_inputs,
        "password_inputs": password_inputs,
        "checkbox_inputs": checkbox_inputs,
        "submit_inputs": submit_inputs,
        "image_submit_inputs": image_submit_inputs,
        "postback_targets": postback_targets,
        "has_recaptcha": has_recaptcha,
    }


def authenticate_neworder_backoffice(
    force_refresh: bool = False,
    override_company: str = "",
    override_username: str = "",
    override_password: str = "",
) -> dict:
    """
    Authenticates against NewOrder Cellular & BackOffice (https://cellular.neworder.co.il/heb/login.aspx)
    with a 3-Tier Zero-Cost CAPTCHA Bypass (0 ₪ — no need for the 150 ₪ + VAT API!):
    Tier 0: Human-authenticated Browser Bridge / NEWORDER_COOKIE session (bypasses login.aspx & 'I am not a robot' 100%, kept alive 24/7!).
    Tier 1: ASP.NET 3-field login (NEWORDER_COMPANY, NEWORDER_USERNAME, NEWORDER_PASSWORD) + automatic checkbox marking ('on').
    Tier 2: Mobile App / AJAX WebMethod login headers (which often bypass web reCAPTCHA).
    """
    now_ts = std_time.time()
    has_overrides = bool(override_company or override_username or override_password)
    render_base = (RENDER_EXTERNAL_URL or "https://ns-whatsapp-agent-1.onrender.com").strip().rstrip("/")
    bridge_url = f"{render_base}/pos_bridge"

    # Tier 0: Check active Browser Bridge session or NEWORDER_COOKIE
    if NEWORDER_COOKIE:
        parsed_env_c = parse_cookie_header_string(NEWORDER_COOKIE)
        if parsed_env_c:
            NEWORDER_SESSION_CACHE.setdefault("cookies", {}).update(parsed_env_c)

    existing_cookies = NEWORDER_SESSION_CACHE.get("cookies") or {}
    if existing_cookies and not has_overrides:
        if not force_refresh and NEWORDER_SESSION_CACHE.get("authenticated_at", 0) > 0 and (now_ts - NEWORDER_SESSION_CACHE["authenticated_at"] < 1500):
            return {
                "ok": True,
                "cached": True,
                "mode": "browser_bridge_or_cookie",
                "landing_url": NEWORDER_SESSION_CACHE.get("landing_url") or f"{NEWORDER_BASE_URL}/default.aspx",
                "discovered_pages": NEWORDER_SESSION_CACHE.get("discovered_pages", []),
                "cookies": existing_cookies,
                "token": NEWORDER_SESSION_CACHE.get("token", ""),
            }
        # Verify if the existing cookie session is alive on an internal page (bypassing login.aspx!)
        try:
            test_target = NEWORDER_SESSION_CACHE.get("landing_url") or f"{NEWORDER_BASE_URL}/default.aspx"
            if "login.aspx" in test_target.lower():
                test_target = f"{NEWORDER_BASE_URL}/default.aspx"
            with httpx.Client(timeout=6.0, follow_redirects=True) as c_sess:
                c_resp = c_sess.get(
                    test_target,
                    cookies=existing_cookies,
                    headers={"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) Chrome/128.0.0.0 Safari/537.36"},
                )
                if c_resp.status_code == 200 and "login.aspx" not in str(c_resp.url).lower():
                    for ck, cv in c_sess.cookies.items():
                        existing_cookies[ck] = cv
                    NEWORDER_SESSION_CACHE["cookies"] = existing_cookies
                    NEWORDER_SESSION_CACHE["authenticated_at"] = now_ts
                    NEWORDER_SESSION_CACHE["landing_url"] = str(c_resp.url)
                    save_neworder_session_cache()
                    return {
                        "ok": True,
                        "mode": "browser_bridge_session_alive",
                        "landing_url": str(c_resp.url),
                        "discovered_pages": NEWORDER_SESSION_CACHE.get("discovered_pages", []),
                        "cookies": existing_cookies,
                        "token": "",
                    }
        except Exception:
            pass
        # Also if Browser Bridge already pushed menus/tables directly from Eran's browser, treat as connected!
        if NEWORDER_SESSION_CACHE.get("menus_found") or NEWORDER_SESSION_CACHE.get("pages_scanned"):
            return {
                "ok": True,
                "mode": "browser_bridge_synced_data",
                "landing_url": NEWORDER_SESSION_CACHE.get("landing_url") or f"{NEWORDER_BASE_URL}/default.aspx",
                "discovered_pages": NEWORDER_SESSION_CACHE.get("discovered_pages", []),
                "cookies": existing_cookies,
                "token": "",
            }

    if POS_API_KEY and not has_overrides:
        tok = f"Bearer {POS_API_KEY}" if not POS_API_KEY.lower().startswith("bearer ") else POS_API_KEY
        NEWORDER_SESSION_CACHE["token"] = tok
        NEWORDER_SESSION_CACHE["authenticated_at"] = now_ts
        return {"ok": True, "mode": "api_key", "token": tok, "cookies": {}}

    eff_company = (override_company or NEWORDER_COMPANY).strip()
    eff_username = (override_username or NEWORDER_USERNAME).strip()
    eff_password = (override_password or NEWORDER_PASSWORD).strip()

    if not eff_username or not eff_password:
        return {
            "ok": False,
            "reason": f"חסרים פרטי התחברות ב-Render (הגדר NEWORDER_COMPANY, NEWORDER_USERNAME ו-NEWORDER_PASSWORD או התחבר בלחיצה אחת דרך {bridge_url} לעקיפת 'אני לא רובוט' ב-0 ₪)",
            "bridge_url": bridge_url,
        }

    login_url = POS_API_URL or DEFAULT_NEWORDER_URL
    ua_headers = {
        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/128.0.0.0 Safari/537.36",
        "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,application/json,*/*;q=0.8",
        "Accept-Language": "he-IL,he;q=0.9,en-US;q=0.8,en;q=0.7",
    }

    # Tier 1: ASP.NET WebForms Login Flow (3 fields + auto-checking any checkbox inputs!)
    try:
        with httpx.Client(timeout=8.0, follow_redirects=True, headers=ua_headers) as sess:
            get_resp = sess.get(login_url)
            html_body = get_resp.text or ""
            parsed_form = _parse_aspnet_form_inputs(html_body)
            has_recaptcha = bool(parsed_form.get("has_recaptcha"))
            NEWORDER_SESSION_CACHE["has_recaptcha"] = has_recaptcha

            form_data = dict(parsed_form["hidden_fields"])
            detected_fields = (
                list(parsed_form["hidden_fields"].keys())
                + parsed_form["text_inputs"]
                + parsed_form["password_inputs"]
                + [c[0] for c in parsed_form.get("checkbox_inputs", [])]
                + [s[0] for s in parsed_form["submit_inputs"]]
            )
            NEWORDER_SESSION_CACHE["detected_form_fields"] = detected_fields

            # Automatically check all checkbox inputs (e.g. simple 'אני לא רובוט' / 'זכור אותי' checkbox)
            for chk_name, chk_val in parsed_form.get("checkbox_inputs", []):
                form_data[chk_name] = chk_val or "on"

            # 1A. Populate discovered Company Name field(s) (שם חברה)
            if parsed_form["company_inputs"]:
                for c_field in parsed_form["company_inputs"]:
                    form_data[c_field] = eff_company
            elif eff_company:
                for fallback_c in [
                    "txtCompany", "txtCompanyName", "txtComp", "txtClient", "txtAccount", "txtBranch",
                    "Company", "CompanyName", "company",
                    "ctl00$ContentPlaceHolder1$txtCompany", "ctl00$ContentPlaceHolder1$txtCompanyName",
                    "ctl00$MainContent$txtCompany", "ctl00$MainContent$txtCompanyName",
                ]:
                    form_data[fallback_c] = eff_company

            # 1B. Populate discovered Username field(s) (שם משתמש)
            if parsed_form["user_inputs"]:
                for u_field in parsed_form["user_inputs"]:
                    form_data[u_field] = eff_username
            else:
                for fallback_u in [
                    "txtUserName", "txtUser", "UserName", "username",
                    "ctl00$ContentPlaceHolder1$txtUserName", "ctl00$ContentPlaceHolder1$txtUser",
                    "ctl00$MainContent$txtUserName", "ctl00$MainContent$txtUser",
                ]:
                    form_data[fallback_u] = eff_username

            # 1C. Populate discovered Password field(s) (סיסמה)
            if parsed_form["password_inputs"]:
                for p_field in parsed_form["password_inputs"]:
                    form_data[p_field] = eff_password
            else:
                for fallback_p in [
                    "txtPassword", "txtPass", "Password", "password",
                    "ctl00$ContentPlaceHolder1$txtPassword", "ctl00$ContentPlaceHolder1$txtPass",
                    "ctl00$MainContent$txtPassword", "ctl00$MainContent$txtPass",
                ]:
                    form_data[fallback_p] = eff_password

            # 1D. Populate submit button, image button (.x/.y), or __doPostBack target
            if parsed_form["submit_inputs"]:
                btn_name, btn_val = parsed_form["submit_inputs"][0]
                form_data[btn_name] = btn_val or "כניסה"
                if btn_name in parsed_form.get("image_submit_inputs", []):
                    form_data[f"{btn_name}.x"] = "12"
                    form_data[f"{btn_name}.y"] = "12"
            if parsed_form.get("postback_targets") and not parsed_form["submit_inputs"]:
                pb_t, pb_a = parsed_form["postback_targets"][0]
                form_data["__EVENTTARGET"] = pb_t
                form_data["__EVENTARGUMENT"] = pb_a
            else:
                form_data.setdefault("__EVENTTARGET", "")
                form_data.setdefault("__EVENTARGUMENT", "")

            mapped_summary = {
                "company_fields": parsed_form["company_inputs"],
                "user_fields": parsed_form["user_inputs"],
                "password_fields": parsed_form["password_inputs"],
                "checkbox_fields": [c[0] for c in parsed_form.get("checkbox_inputs", [])],
                "submit_fields": [s[0] for s in parsed_form["submit_inputs"]],
                "postback_targets": [p[0] for p in parsed_form.get("postback_targets", [])],
                "has_recaptcha": has_recaptcha,
            }

            post_headers = dict(ua_headers)
            post_headers["Referer"] = str(get_resp.url)
            post_headers["Content-Type"] = "application/x-www-form-urlencoded"

            post_resp = sess.post(str(get_resp.url), data=form_data, headers=post_headers)
            all_cookies = {k: v for k, v in sess.cookies.items()}
            final_url = str(post_resp.url)
            post_html = post_resp.text or ""
            post_parsed = _parse_aspnet_form_inputs(post_html)

            # Discover internal .aspx pages linked after login
            discovered_links = sorted(list(set(
                m.group(1) for m in re.finditer(r"href\s*=\s*[\x22\x27]([^\x22\x27]*\.aspx[^\x22\x27]*)[\x22\x27]", post_html, re.IGNORECASE)
                if "login.aspx" not in m.group(1).lower() and "forgot" not in m.group(1).lower()
            )))[:25]

            redirected_away = "login.aspx" not in final_url.lower()
            still_has_password_box = bool(post_parsed.get("password_inputs"))
            has_explicit_auth_cookie = any(".aspxauth" in k.lower() or "auth" in k.lower() for k in all_cookies.keys())
            has_logout_link = any(w in post_html.lower() for w in ["logout", "יציאה", "התנתק", "signout", "logoff"])

            if redirected_away or has_explicit_auth_cookie or (has_logout_link and not still_has_password_box):
                NEWORDER_SESSION_CACHE["cookies"] = all_cookies
                NEWORDER_SESSION_CACHE["authenticated_at"] = now_ts
                NEWORDER_SESSION_CACHE["landing_url"] = final_url
                NEWORDER_SESSION_CACHE["discovered_pages"] = discovered_links
                save_neworder_session_cache()
                return {
                    "ok": True,
                    "mode": "aspnet_webforms",
                    "login_url": login_url,
                    "landing_url": final_url,
                    "discovered_pages": discovered_links,
                    "detected_form_fields": detected_fields,
                    "mapped_fields": mapped_summary,
                    "cookies": all_cookies,
                    "token": "",
                }

            # Tier 2: Try ASP.NET AJAX WebMethod / Mobile App endpoints (often bypass web CAPTCHA!)
            for wm in ["Login", "CheckLogin", "UserLogin", "Authenticate", "AppLogin", "MobileLogin"]:
                try:
                    wm_url = f"{login_url.split('?')[0]}/{wm}"
                    wm_resp = sess.post(
                        wm_url,
                        json={
                            "company": eff_company,
                            "companyName": eff_company,
                            "Company": eff_company,
                            "userName": eff_username,
                            "username": eff_username,
                            "password": eff_password,
                        },
                        headers={
                            "Content-Type": "application/json; charset=utf-8",
                            "Accept": "application/json",
                            "X-Requested-With": "XMLHttpRequest",
                            "User-Agent": "NewOrderApp/2.0 (Android; Mobile)",
                        },
                    )
                    if wm_resp.status_code == 200 and ("d" in wm_resp.text or "token" in wm_resp.text.lower() or len(sess.cookies) > len(get_resp.cookies)):
                        all_cookies = {k: v for k, v in sess.cookies.items()}
                        NEWORDER_SESSION_CACHE["cookies"] = all_cookies
                        NEWORDER_SESSION_CACHE["authenticated_at"] = now_ts
                        NEWORDER_SESSION_CACHE["landing_url"] = wm_url
                        save_neworder_session_cache()
                        return {
                            "ok": True,
                            "mode": "aspnet_webmethod",
                            "login_url": wm_url,
                            "discovered_pages": discovered_links,
                            "detected_form_fields": detected_fields,
                            "mapped_fields": mapped_summary,
                            "cookies": all_cookies,
                            "token": "",
                        }
                except Exception:
                    continue

            captcha_note = (
                f"דף הכניסה כולל אימות 'אני לא רובוט' (CAPTCHA). אין צורך לשלם 150 ₪ + מע\"מ על API! "
                f"פתח את {bridge_url} כדי לחבר את הדפדפן שלך בלחיצה אחת ופריצת הסשן תישמר 24/7 אוטומטית!"
                if has_recaptcha or "רובוט" in html_body or "robot" in html_body.lower()
                else f"השרת הגיע לדף login.aspx אך נחסם ע\"י אימות 'אני לא רובוט' או פרטי כניסה. לחיבור מיידי בחינם (0 ₪) פתח את: {bridge_url}"
            )
            return {
                "ok": False,
                "reason": captcha_note,
                "has_recaptcha": has_recaptcha,
                "bridge_url": bridge_url,
                "login_url": login_url,
                "final_url": final_url,
                "detected_form_fields": detected_fields,
                "mapped_fields": mapped_summary,
                "cookies_count": len(all_cookies),
            }
    except Exception as e_auth:
        return {
            "ok": False,
            "reason": f"שגיאת תקשורת מול שרת NewOrder ({e_auth}). ניתן לחבר ישירות מהדפדפן ב-0 ₪ דרך {bridge_url}",
            "bridge_url": bridge_url,
            "login_url": login_url,
        }


def build_neworder_auth_headers_and_cookies() -> tuple[dict, dict]:
    """Returns (headers, cookies) authenticated via Browser Bridge Cookie, NEWORDER_COOKIE, ASP.NET login.aspx, or API Key."""
    headers = {
        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/128.0.0.0 Safari/537.36",
        "Accept": "application/json, text/html, */*",
    }
    cookies = {}
    if NEWORDER_COOKIE:
        cookies.update(parse_cookie_header_string(NEWORDER_COOKIE))
    if NEWORDER_SESSION_CACHE.get("cookies"):
        cookies.update(NEWORDER_SESSION_CACHE["cookies"])
    if POS_API_KEY:
        headers["Authorization"] = f"Bearer {POS_API_KEY}" if not POS_API_KEY.lower().startswith("bearer ") else POS_API_KEY
        headers["X-API-Key"] = POS_API_KEY
        headers["apiKey"] = POS_API_KEY
    elif not cookies and NEWORDER_USERNAME and NEWORDER_PASSWORD:
        auth_res = authenticate_neworder_backoffice()
        if auth_res.get("ok"):
            if auth_res.get("token"):
                headers["Authorization"] = auth_res["token"]
            if auth_res.get("cookies"):
                cookies = auth_res["cookies"]
    return headers, cookies


def _extract_html_table_rows(html_text: str) -> list[list[str]]:
    """Extracts clean text cells from HTML <tr><td>...</td></tr> tables in NewOrder .aspx pages."""
    rows_out = []
    for m_tr in re.finditer(r"<tr\b[^>]*>(.*?)</tr>", html_text or "", flags=re.IGNORECASE | re.DOTALL):
        tr_inner = m_tr.group(1)
        cells = []
        for m_td in re.finditer(r"<t[dh]\b[^>]*>(.*?)</t[dh]>", tr_inner, flags=re.IGNORECASE | re.DOTALL):
            cell_txt = re.sub(r"<[^>]+>", " ", m_td.group(1))
            cell_txt = re.sub(r"&nbsp;|&#160;", " ", cell_txt)
            cell_txt = re.sub(r"\s+", " ", cell_txt).strip()
            cells.append(cell_txt)
        if cells and any(cells):
            rows_out.append(cells)
    return rows_out


def _extract_html_menus_and_links(html_text: str, base_url: str = "") -> list[dict]:
    """
    Extracts all navigation menu items (<a href="...">Title</a>) and frames (<iframe/frame src="...">)
    from NewOrder Cellular / BackOffice HTML pages, classifying each menu into its functional category.
    """
    menus = []
    seen_urls = set()
    eff_base = (base_url or NEWORDER_BASE_URL).rstrip("/")

    def _classify_menu(title_s: str, href_s: str) -> str:
        combined = f"{title_s} {href_s}".lower()
        if any(k in combined for k in ["תיקון", "תיקונים", "מעבדה", "קריאות", "קריאת", "שירות", "כרטיס", "repair", "ticket", "service", "lab"]):
            return "מעבדה וקריאות שירות"
        if any(k in combined for k in ["מלאי", "פריט", "פריטים", "מוצר", "מוצרים", "מחירון", "קטלוג", "item", "inv", "prod", "stock", "price"]):
            return "מלאי, פריטים ומחירים"
        if any(k in combined for k in ["לקוח", "לקוחות", "איש קשר", "client", "cust", "contact"]):
            return "לקוחות"
        if any(k in combined for k in ["מכירה", "מכירות", "קופה", "חשבונית", "הזמנה", "הזמנות", "order", "sale", "pos", "invoice"]):
            return "קופה והזמנות"
        if any(k in combined for k in ["דוח", "דוחות", "סטטיסטיקה", "report", "stat"]):
            return "דוחות"
        return "תפריט כללי"

    # 1. Extract <a href="...">Menu Title</a>
    for m_a in re.finditer(r"<a\b([^>]+)>(.*?)</a>", html_text or "", flags=re.IGNORECASE | re.DOTALL):
        attrs, inner_html = m_a.group(1), m_a.group(2)
        m_href = re.search(r"\bhref\s*=\s*[\x22\x27]([^\x22\x27]+)[\x22\x27]", attrs, re.IGNORECASE)
        if not m_href:
            continue
        raw_href = m_href.group(1).strip()
        if not raw_href or raw_href.startswith(("#", "javascript:", "mailto:", "tel:")):
            continue
        if "login.aspx" in raw_href.lower() or "logout" in raw_href.lower():
            continue
        title_clean = re.sub(r"<[^>]+>", " ", inner_html)
        title_clean = re.sub(r"&nbsp;|&#160;", " ", title_clean)
        title_clean = re.sub(r"\s+", " ", title_clean).strip()
        if not title_clean:
            m_title_attr = re.search(r"\b(?:title|aria-label)\s*=\s*[\x22\x27]([^\x22\x27]+)[\x22\x27]", attrs, re.IGNORECASE)
            title_clean = m_title_attr.group(1).strip() if m_title_attr else raw_href.split("/")[-1].split("?")[0]

        full_url = raw_href if raw_href.startswith("http") else f"{eff_base}/{raw_href.lstrip('/')}"
        if full_url not in seen_urls:
            seen_urls.add(full_url)
            menus.append({
                "title": title_clean[:60],
                "url": full_url,
                "raw_href": raw_href,
                "category": _classify_menu(title_clean, raw_href),
            })

    # 2. Extract <iframe src="..."> and <frame src="..."> (common in ASP.NET ERP portals)
    for m_fr in re.finditer(r"<i?frame\b([^>]+)>", html_text or "", flags=re.IGNORECASE):
        attrs = m_fr.group(1)
        m_src = re.search(r"\bsrc\s*=\s*[\x22\x27]([^\x22\x27]+)[\x22\x27]", attrs, re.IGNORECASE)
        if not m_src:
            continue
        raw_src = m_src.group(1).strip()
        if not raw_src or raw_src.startswith(("javascript:", "about:")):
            continue
        full_url = raw_src if raw_src.startswith("http") else f"{eff_base}/{raw_src.lstrip('/')}"
        if full_url not in seen_urls:
            seen_urls.add(full_url)
            menus.append({
                "title": f"חלונית מערכת ({raw_src.split('/')[-1].split('?')[0]})",
                "url": full_url,
                "raw_href": raw_src,
                "category": _classify_menu(raw_src, raw_src),
            })

    return menus


def is_confidential_pos_inquiry(text: str) -> bool:
    """
    Blocks any customer attempt to ask for confidential store/POS data:
    - Cost price / dealer purchase price (מחיר עלות, מחיר קנייה, כמה עולה לך מהיבואן)
    - Supplier / Importer identity (מי הספק, מאיזה יבואן אתם מביאים, מי היבואנים שלכם)
    - Store profit / margin / revenue reports (כמה רווח, אחוז רווח, דוח מכירות, מחזור קופה)
    - Exact internal stock counts across the store (כמה יחידות בדיוק רשום בקופה)
    """
    clean = auto_fix_common_hebrew_typos((text or "").strip().lower())
    if not clean:
        return False
    confidential_patterns = [
        r"מחיר\s+(?:ה?עלות|ה?קנייה|ה?קניה|ספק|יבואן|סיטונאי)",
        r"כמה\s+(?:זה\s+)?עולה\s+(?:לך|לכם|לחנות|למעבדה)\b",
        r"בכמה\s+(?:אתה\s+|אתם\s+)?(?:קונה|קונים|מביא|מביאים)",
        r"(?:מי|איזה)\s+(?:ה?ספק|ה?ספקים|ה?יבואן|ה?יבואנים)",
        r"מאיזה\s+(?:ספק|יבואן)\s+(?:אתה|אתם)",
        r"כמה\s+(?:אתה\s+|אתם\s+)?(?:מרוויח|מרוויחים|רווח)",
        r"(?:אחוז\s+רווח|דוח\s+קופה|דוחות\s+קופה|מחזור\s+מכירות)",
        r"כמה\s+יחידות\s+(?:בדיוק\s+)?(?:רשום|יש\s+בקופה)",
        r"רשום\s+(?:לך\s+|לכם\s+)?בקופה",
    ]
    return any(re.search(p, clean) for p in confidential_patterns)


def get_confidential_pos_block_reply() -> str:
    """Polite customer-facing refusal when asked for confidential POS data (cost price, suppliers, margins, etc.)."""
    return (
        "אנו מוסרים מידע אך ורק לגבי מחירי המכירה לצרכן וזמינות המוצרים עבורך בחנות. 😊📱\n"
        "באיזה מכשיר או מוצר תרצה להתעניין כדי שאבדוק עבורך מחיר משוערך וזמינות במלאי?"
    )


def _parse_pos_price_cell(cell_text: str) -> str:
    """
    Parses a price value from a POS table / Excel / CSV cell, handling:
    - Decimal prices ('380.00', '1,250.00', '49.90')
    - Currency symbols ('380 ₪', '₪420', '380 שח', '380 ש"ח')
    - Plain numeric cells in a price column ('380', '1250')
    Ignores phone numbers, model codes, and SKUs.
    """
    if not cell_text:
        return ""
    s = str(cell_text).strip()
    # Ignore phone numbers and dates
    if re.search(r"\b(?:05[0-9]-?[0-9]{7}|0[23489]-?[0-9]{7}|9725[0-9]{8})\b", s):
        return ""
    if re.search(r"\b\d{1,2}[/.]\d{1,2}[/.]\d{2,4}\b", s):
        return ""
    # Strip SKU / barcode prefixes
    s_clean = re.sub(r"\b(?:sku|מקט|מק\"ט|ברקוד|קריאה|מספר)\s*[-:#]?\s*\d+\b", " ", s, flags=re.IGNORECASE)
    # Strip model codes attached to letters (e.g. A15, F21, S24, 128GB, 4G, 5G)
    s_clean = re.sub(r"\b(?:[aAsSmMfFqQgG]\s*-?\s*\d{1,3}|\d{1,4}\s*(?:gb|tb|mb|mah|g)|4x4)\b", " ", s_clean, flags=re.IGNORECASE)
    # Remove thousands commas inside numbers (e.g. '1,250.00' -> '1250.00')
    s_clean = re.sub(r"(?<=\d),(?=\d{3}(?:\b|\.|$))", "", s_clean)

    # 1. Explicit currency match
    m_cur = re.search(
        r"(?:₪|\$)?\s*(\d{2,5}(?:\.\d{1,2})?)\s*(?:₪|ש\"ח|ש''ח|שח|שקלים|שקל|nis)(?:\b|$)|(?:₪)\s*(\d{2,5}(?:\.\d{1,2})?)\b",
        s_clean,
        flags=re.IGNORECASE,
    )
    if m_cur:
        num_str = m_cur.group(1) or m_cur.group(2)
        val = int(round(float(num_str)))
        if 15 <= val <= 9500:
            return str(val)

    # 2. Pure numeric / decimal cell (e.g. '380.00' or '420' in an Excel/POS column)
    m_pure = re.fullmatch(r"[₪\s]*(\d{2,4}(?:\.\d{1,2})?)[₪\s]*", s_clean.strip())
    if m_pure:
        val = int(round(float(m_pure.group(1))))
        if 15 <= val <= 9500:
            return str(val)

    # 3. Fallback to extract_price_nis (after stripping .00 decimals)
    s_no_dec = re.sub(r"\.\d{1,2}\b", "", s_clean)
    return extract_price_nis(s_no_dec)


def _extract_sale_price_only_from_cells(cells: list[str], col_map: dict = None) -> tuple[str, str, str]:
    """
    Extracts ONLY (sku, clean_product_name, sale_price_nis) from a POS table / Excel / CSV row,
    while STRICTLY blocking and discarding:
    - Cost / Purchase price columns (מחיר עלות / מחיר קנייה / עלות ספק)
    - Supplier / Importer columns (שם ספק / יבואן)
    - Profit / Margin columns (רווח / אחוז רווח)
    - Stock quantity numbers (כמות במלאי)
    If both Cost Price and Sale Price appear in a row without headers, always selects the higher Retail Sale Price!
    """
    if not cells:
        return "", "", ""
    col_map = col_map or {}
    cost_cols = col_map.get("cost_cols", set())
    supplier_cols = col_map.get("supplier_cols", set())
    qty_cols = col_map.get("qty_cols", set())
    sale_col = col_map.get("sale_col")
    name_col = col_map.get("name_col")
    sku_col = col_map.get("sku_col")

    cost_cell_markers = ["עלות", "קנייה", "קניה", "ספק", "יבואן", "רווח", "סיטונאי", "cost", "buy", "margin", "supplier"]
    sale_cell_markers = ["מכירה", "לצרכן", "מחירון", "ללקוח", "sale", "retail"]

    # 1. Determine SKU
    sku_val = ""
    if sku_col is not None and sku_col < len(cells):
        sku_val = str(cells[sku_col]).strip()[:40]
    elif len(cells) >= 3 and re.fullmatch(r"[A-Za-z0-9\-_]{2,20}", str(cells[0]).strip()):
        sku_val = str(cells[0]).strip()[:40]

    # 2. Determine Clean Product Name (never include supplier, cost, or pure numbers)
    prod_name = ""
    if name_col is not None and name_col < len(cells):
        prod_name = str(cells[name_col]).strip()
    else:
        for idx, c in enumerate(cells):
            if idx in cost_cols or idx in supplier_cols or idx in qty_cols or idx == sale_col or idx == sku_col:
                continue
            c_str = str(c).strip()
            if not c_str or c_str.isdigit() or re.fullmatch(r"[\d.,₪ש\"ח\s\-]+", c_str):
                continue
            if idx == 0 and len(cells) >= 3 and re.match(r"^(?:sku|מקט|מק\"ט|ברקוד|\d{3,})", c_str, re.IGNORECASE):
                continue
            if any(m in c_str.lower() for m in ["עלות:", "ספק:", "יבואן:", "רווח:"]):
                continue
            if re.search(r"[א-תa-zA-Z]", c_str):
                prod_name = c_str
                break

    # Strip any inline confidential annotations from prod_name (e.g. "(יבואן: X)" or "עלות 200")
    prod_name = re.sub(r"\([^)]*(?:יבואן|ספק|עלות|קנייה|קניה|רווח)[^)]*\)", "", prod_name, flags=re.IGNORECASE)
    prod_name = re.sub(r"\b(?:יבואן|ספק|עלות|מחיר\s+עלות|קנייה|קניה)\s*[:\-]?\s*[^\s|,]+", "", prod_name, flags=re.IGNORECASE).strip(" -|,:")

    # 3. Extract Customer Sale Price ONLY (never Cost Price!)
    sale_price_val = ""
    if sale_col is not None and sale_col < len(cells):
        sale_price_val = _parse_pos_price_cell(str(cells[sale_col]))

    if not sale_price_val:
        explicit_sale_candidates = []
        general_price_candidates = []
        for idx, c in enumerate(cells):
            if idx in cost_cols or idx in supplier_cols or idx in qty_cols or idx == sku_col or idx == name_col:
                continue
            if idx == 0 and len(cells) > 2 and sku_val == str(c).strip():
                continue
            c_str = str(c).strip()
            c_low = c_str.lower()
            if any(cm in c_low for cm in cost_cell_markers):
                continue
            p_nis = _parse_pos_price_cell(c_str)
            if p_nis and p_nis.isdigit():
                val_i = int(p_nis)
                if 15 <= val_i <= 9500:
                    if any(sm in c_low for sm in sale_cell_markers):
                        explicit_sale_candidates.append(val_i)
                    else:
                        general_price_candidates.append(val_i)

        if explicit_sale_candidates:
            sale_price_val = str(max(explicit_sale_candidates))
        elif general_price_candidates:
            # CRITICAL SAFETY: When a headerless row has both Cost Price (lower) and Sale Price (higher),
            # max() guarantees we take the Customer Sale Price and NEVER the lower Cost Price!
            sale_price_val = str(max(general_price_candidates))

    return sku_val, prod_name[:80], sale_price_val


def _parse_inventory_file_bytes(file_bytes: bytes, filename: str = "") -> list[list[str]]:
    """
    Universal zero-dependency parser for NewOrder BackOffice / POS inventory exports:
    1. .xlsx (Excel OpenXML ZIP archive via standard library zipfile + xml.etree.ElementTree)
    2. .xls (HTML <table> export, XML SpreadsheetML <Row><Cell><Data>, or TSV)
    3. .csv / .tsv / .txt (UTF-8, UTF-16, Windows-1255 / CP1255 Hebrew encodings, comma/tab/pipe/dash separated)
    """
    import zipfile
    import io
    import csv
    import xml.etree.ElementTree as ET

    if not file_bytes:
        return []

    rows_out = []
    fn_low = (filename or "").lower()

    # 1. Check if it's a ZIP-based .xlsx file (starts with PK\x03\x04)
    if file_bytes[:4] == b"PK\x03\x04" or fn_low.endswith(".xlsx"):
        try:
            with zipfile.ZipFile(io.BytesIO(file_bytes)) as zf:
                shared_strings = []
                if "xl/sharedStrings.xml" in zf.namelist():
                    ss_root = ET.fromstring(zf.read("xl/sharedStrings.xml"))
                    for si in ss_root.iter():
                        if si.tag.endswith("}si") or si.tag == "si":
                            texts = [t.text or "" for t in si.iter() if t.tag.endswith("}t") or t.tag == "t"]
                            shared_strings.append("".join(texts).strip())
                sheet_files = sorted([n for n in zf.namelist() if n.startswith("xl/worksheets/sheet") and n.endswith(".xml")])
                for sf in sheet_files:
                    sh_root = ET.fromstring(zf.read(sf))
                    for row_el in sh_root.iter():
                        if not (row_el.tag.endswith("}row") or row_el.tag == "row"):
                            continue
                        row_cells = []
                        for c_el in row_el:
                            if not (c_el.tag.endswith("}c") or c_el.tag == "c"):
                                continue
                            c_type = c_el.attrib.get("t", "")
                            val_txt = ""
                            if c_type == "inlineStr":
                                val_txt = "".join([t.text or "" for t in c_el.iter() if t.tag.endswith("}t") or t.tag == "t"]).strip()
                            else:
                                v_el = next((ch for ch in c_el if ch.tag.endswith("}v") or ch.tag == "v"), None)
                                if v_el is not None and v_el.text is not None:
                                    raw_v = v_el.text.strip()
                                    if c_type == "s" and raw_v.isdigit() and int(raw_v) < len(shared_strings):
                                        val_txt = shared_strings[int(raw_v)]
                                    else:
                                        val_txt = raw_v
                            row_cells.append(val_txt)
                        if any(row_cells):
                            rows_out.append(row_cells)
            if rows_out:
                return rows_out
        except Exception as e_xlsx:
            print(f"[XLSX Parse Notice]: {e_xlsx}")

    # 2. Decode text using UTF-8-SIG, UTF-16, or Hebrew Windows-1255 (cp1255)
    decoded_text = ""
    for enc in ("utf-8-sig", "utf-16", "cp1255", "iso-8859-8", "latin-1"):
        try:
            decoded_text = file_bytes.decode(enc)
            if any("\u0590" <= ch <= "\u05ff" for ch in decoded_text) or enc in ("utf-8-sig", "cp1255"):
                break
        except Exception:
            continue

    if not decoded_text:
        return []

    # 3. Check if it's an HTML table (.xls exported from ASP.NET GridView)
    if "<tr" in decoded_text.lower() and "<td" in decoded_text.lower():
        html_rows = _extract_html_table_rows(decoded_text)
        if html_rows:
            return html_rows

    # 4. Check if it's XML SpreadsheetML (<Row><Cell><Data>)
    if "<row" in decoded_text.lower() and "<data" in decoded_text.lower():
        try:
            for m_r in re.finditer(r"<Row\b[^>]*>(.*?)</Row>", decoded_text, flags=re.IGNORECASE | re.DOTALL):
                cells = [
                    re.sub(r"<[^>]+>", "", m_d.group(1)).strip()
                    for m_d in re.finditer(r"<Data\b[^>]*>(.*?)</Data>", m_r.group(1), flags=re.IGNORECASE | re.DOTALL)
                ]
                if any(cells):
                    rows_out.append(cells)
            if rows_out:
                return rows_out
        except Exception:
            pass

    # 5. Parse as CSV / TSV / Pipe / Dash-separated lines
    lines = [ln.strip() for ln in decoded_text.splitlines() if ln.strip()]
    for ln in lines:
        if "\t" in ln:
            cells = [c.strip().strip('"') for c in ln.split("\t") if c.strip()]
        elif "|" in ln:
            cells = [c.strip().strip('"') for c in ln.split("|") if c.strip()]
        elif ";" in ln:
            cells = [c.strip().strip('"') for c in ln.split(";") if c.strip()]
        elif "," in ln and len(ln.split(",")) >= 2:
            try:
                cells = [c.strip() for c in next(csv.reader([ln])) if c.strip()]
            except Exception:
                cells = [c.strip() for c in ln.split(",") if c.strip()]
        elif re.search(r"\s+[-:–]\s+", ln):
            cells = [c.strip() for c in re.split(r"\s+[-:–]\s+", ln) if c.strip()]
        else:
            # Handle 'נוקיה 215 כשר 380' (product name followed by price at end of line)
            m_line_p = re.match(r"^(.+?)\s+(\d{2,4}(?:\.\d{1,2})?)\s*(?:₪|ש\"ח|שח|שקל)?$", ln)
            if m_line_p:
                cells = [m_line_p.group(1).strip(), m_line_p.group(2).strip()]
            else:
                cells = [ln]
        if len(cells) >= 2:
            rows_out.append(cells)

    return rows_out


def _ingest_neworder_rows_into_db(rows: list[list[str]], source_label: str = "") -> dict:
    """
    Automatically classifies and imports table rows scraped or bridged from NewOrder Cellular / BackOffice
    into SQLite (`lab_repairs` for repair tickets and `pos_inventory` for products/prices).
    ENFORCES STRICT POS CONFIDENTIALITY:
    - Maps table headers to separate Customer Sale Price (מחיר מכירה / לצרכן) from Store Cost Price (מחיר עלות / קנייה).
    - Discards Cost Prices, Supplier/Importer names, Profit margins, and exact stock counts.
    - Stores ONLY clean product names and Customer Sale Prices in `pos_inventory`.
    """
    repairs_added = 0
    items_added = 0
    if not rows:
        return {"repairs_added": 0, "items_added": 0}

    # Never ingest rows from financial/supplier/cost report menus into customer-facing inventory
    if any(b in (source_label or "").lower() for b in ["דוח", "רווח", "ספקים", "עלות", "כספים", "הנהלת חשבונות"]):
        return {"repairs_added": 0, "items_added": 0}

    repair_status_words = ["מוכן לאיסוף", "מוכן", "בבדיקה", "בתיקון", "ממתין לחלק", "ממתין לאישור", "הושלם", "בטיפול", "נמסר", "פתוח"]
    header_keywords = ["מספר קריאה", "שם לקוח", "טלפון", "סטטוס", "תיאור פריט", "שם פריט", "שם מוצר", "מק\"ט", "מקט", "מחיר", "עלות", "מכירה", "כמות", "ספק", "יבואן"]

    col_map = {
        "sale_col": None,
        "cost_cols": set(),
        "supplier_cols": set(),
        "qty_cols": set(),
        "name_col": None,
        "sku_col": None,
    }

    try:
        conn = sqlite3.connect(DB_PATH)
        for cells in rows:
            clean_cells = [str(c).strip() for c in cells if str(c).strip()]
            if len(clean_cells) < 2:
                continue
            row_joined = " | ".join(clean_cells)
            row_low = row_joined.lower()

            # Detect & map table header row (never treat a data row containing numeric price/SKU cells as a header!)
            has_numeric_data_cell = any(re.fullmatch(r"[₪\s]*\d+(?:[.,]\d+)?[₪\s]*", c) for c in clean_cells)
            if not has_numeric_data_cell and sum(1 for hw in header_keywords if hw in row_low) >= 2 and not re.search(r"\b05[0-9]-?[0-9]{7}\b", row_joined):
                for idx, h_cell in enumerate(clean_cells):
                    hl = h_cell.lower()
                    if any(w in hl for w in ["עלות", "קנייה", "קניה", "סיטונאי", "רווח", "cost", "buy", "margin"]):
                        col_map["cost_cols"].add(idx)
                    elif any(w in hl for w in ["ספק", "יבואן", "supplier", "vendor", "importer"]):
                        col_map["supplier_cols"].add(idx)
                    elif any(w in hl for w in ["כמות", "יתרה", "מלאי", "qty", "stock", "quantity"]):
                        col_map["qty_cols"].add(idx)
                    elif any(w in hl for w in ["מכירה", "לצרכן", "מחירון", "ללקוח", "sale", "retail"]) or ("מחיר" in hl and "עלות" not in hl and "קני" not in hl):
                        col_map["sale_col"] = idx
                    elif any(w in hl for w in ["שם פריט", "תיאור פריט", "שם מוצר", "תיאור", "פריט", "מוצר", "דגם"]):
                        if col_map["name_col"] is None:
                            col_map["name_col"] = idx
                    elif any(w in hl for w in ["מק\"ט", "מקט", "ברקוד", "קוד פריט", "sku", "barcode"]):
                        if col_map["sku_col"] is None:
                            col_map["sku_col"] = idx
                continue

            # 1. Check if row is a Lab Repair Ticket (contains a phone number or repair status keyword)
            m_phone = re.search(r"\b(05[0-9]-?[0-9]{7}|0[23489]-?[0-9]{7}|9725[0-9]{8})\b", row_joined)
            matched_status = next((st for st in repair_status_words if st in row_joined), "")
            if m_phone or (matched_status and ("תיקון" in source_label or "מעבדה" in source_label or "קריא" in source_label)):
                phone_norm = normalize_phone(m_phone.group(1)) if m_phone else ""
                m_tid = re.search(r"\b(\d{3,7})\b", clean_cells[0])
                ticket_id = m_tid.group(1) if m_tid else (f"NO-{phone_norm[-4:]}" if phone_norm else f"NO-{ abs(hash(row_joined)) % 10000 }")
                status_label = matched_status or "בטיפול במעבדה"
                _, _, rep_sale_price = _extract_sale_price_only_from_cells(clean_cells, col_map)
                price_val = rep_sale_price or extract_price_nis(row_joined)
                cust_name = clean_cells[1] if len(clean_cells) > 1 and not re.search(r"\d{4,}", clean_cells[1]) else ""
                dev_model = clean_cells[2] if len(clean_cells) > 2 else ""
                fault_desc = clean_cells[3] if len(clean_cells) > 3 else ""
                conn.execute(
                    """
                    INSERT INTO lab_repairs (ticket_id, phone, customer_name, device_model, fault_desc, status_label, price_nis, notes, updated_at)
                    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
                    ON CONFLICT(ticket_id) DO UPDATE SET
                        phone=CASE WHEN excluded.phone != '' THEN excluded.phone ELSE lab_repairs.phone END,
                        customer_name=CASE WHEN excluded.customer_name != '' THEN excluded.customer_name ELSE lab_repairs.customer_name END,
                        device_model=CASE WHEN excluded.device_model != '' THEN excluded.device_model ELSE lab_repairs.device_model END,
                        fault_desc=excluded.fault_desc,
                        status_label=excluded.status_label,
                        price_nis=CASE WHEN excluded.price_nis != '' THEN excluded.price_nis ELSE lab_repairs.price_nis END,
                        updated_at=excluded.updated_at
                    """,
                    (ticket_id, phone_norm, cust_name, dev_model, fault_desc, status_label, price_val, f"סונכרן מ-NewOrder ({source_label})", datetime.now().isoformat())
                )
                repairs_added += 1
                continue

            # 2. Check if row is an Inventory / Price Item -> Extract ONLY Sale Price and Clean Product Name!
            sku_cand, prod_name, sale_price_val = _extract_sale_price_only_from_cells(clean_cells, col_map)
            if sale_price_val and prod_name and len(prod_name) >= 2 and not prod_name.isdigit():
                if not sku_cand or sku_cand == prod_name:
                    # Include hash of row so multiple importers for the same product name don't overwrite each other's price range!
                    sku_cand = f"{prod_name[:30]}-{abs(hash(row_joined)) % 1000}"
                # CONFIDENTIALITY FIREWALL: Store ONLY clean prod_name in keywords (NEVER store raw row_joined with supplier/cost!)
                conn.execute(
                    """
                    INSERT INTO pos_inventory (sku, product_name, keywords, category, single_price, stock_qty, updated_at)
                    VALUES (?, ?, ?, ?, ?, ?, ?)
                    ON CONFLICT(sku) DO UPDATE SET
                        product_name=excluded.product_name,
                        keywords=excluded.keywords,
                        single_price=excluded.single_price,
                        updated_at=excluded.updated_at
                    """,
                    (sku_cand[:50], prod_name[:80], prod_name[:120], source_label or "NewOrder", int(sale_price_val), 5, datetime.now().isoformat())
                )
                items_added += 1
        conn.commit()
        conn.close()
        if repairs_added > 0:
            sync_cellular_repairs_to_json()
        if items_added > 0:
            sync_pos_inventory_to_json()
    except Exception as e_ing:
        print(f"[NewOrder Row Ingest Notice]: {e_ing}")

    return {"repairs_added": repairs_added, "items_added": items_added}


def explore_neworder_menus_and_data(
    search_query: str = "",
    company: str = "",
    username: str = "",
    password: str = "",
) -> dict:
    """
    Logs into NewOrder Cellular (https://cellular.neworder.co.il/heb/login.aspx) or uses the active
    Browser Bridge session (/pos_bridge), maps out all menus and internal pages, crawls the top
    Lab/Repairs and Inventory/Items menus, and extracts live sample data rows!
    """
    render_base = (RENDER_EXTERNAL_URL or "https://ns-whatsapp-agent-1.onrender.com").strip().rstrip("/")
    bridge_url = f"{render_base}/pos_bridge"

    auth_res = authenticate_neworder_backoffice(
        force_refresh=True,
        override_company=company,
        override_username=username,
        override_password=password,
    )
    if not auth_res.get("ok"):
        return {
            "ok": False,
            "reason": auth_res.get("reason", "ההתחברות לא הצליחה"),
            "has_recaptcha": auth_res.get("has_recaptcha", NEWORDER_SESSION_CACHE.get("has_recaptcha", False)),
            "bridge_url": bridge_url,
            "portal_url": POS_API_URL,
            "company_configured": bool(company or NEWORDER_COMPANY),
            "username_configured": bool(username or NEWORDER_USERNAME),
            "password_configured": bool(password or NEWORDER_PASSWORD),
            "cookie_configured": bool(NEWORDER_COOKIE or NEWORDER_SESSION_CACHE.get("cookies")),
            "detected_form_fields": auth_res.get("detected_form_fields", []),
            "mapped_fields": auth_res.get("mapped_fields", {}),
            "menus_found": NEWORDER_SESSION_CACHE.get("menus_found", []),
            "pages_scanned": NEWORDER_SESSION_CACHE.get("pages_scanned", []),
        }

    headers, cookies = build_neworder_auth_headers_and_cookies()
    if auth_res.get("cookies"):
        cookies = auth_res["cookies"]

    landing_url = auth_res.get("landing_url") or NEWORDER_SESSION_CACHE.get("landing_url") or f"{NEWORDER_BASE_URL}/default.aspx"
    menus_found = list(NEWORDER_SESSION_CACHE.get("menus_found", []))
    pages_scanned = list(NEWORDER_SESSION_CACHE.get("pages_scanned", []))
    search_matches = []
    q_clean = (search_query or "").strip().lower()

    # Search any already-bridged pages first if search_query is provided
    if q_clean and pages_scanned:
        for ps in pages_scanned:
            for s_row in ps.get("sample_rows", []):
                if q_clean in s_row.lower():
                    search_matches.append({"source": ps.get("menu_title", "גשר דפדפן"), "row": s_row})

    try:
        with httpx.Client(timeout=8.0, follow_redirects=True, headers=headers, cookies=cookies) as sess:
            # 1. Fetch landing page after login
            land_resp = sess.get(landing_url)
            if "login.aspx" not in str(land_resp.url).lower():
                land_html = land_resp.text or ""
                live_menus = _extract_html_menus_and_links(land_html, NEWORDER_BASE_URL)
                existing_m_urls = {m["url"] for m in menus_found}
                for lm in live_menus:
                    if lm["url"] not in existing_m_urls:
                        menus_found.append(lm)
                        existing_m_urls.add(lm["url"])

                land_rows = _extract_html_table_rows(land_html)
                if land_rows:
                    _ingest_neworder_rows_into_db(land_rows, "דף הבית")
                    pages_scanned.append({
                        "menu_title": "דף הבית לאחר כניסה",
                        "category": "ראשי",
                        "url": str(land_resp.url),
                        "total_rows": len(land_rows),
                        "sample_rows": [" | ".join(r[:8]) for r in land_rows[:5]],
                    })
                    if q_clean:
                        for r in land_rows:
                            r_str = " | ".join(r)
                            if q_clean in r_str.lower():
                                search_matches.append({"source": "דף הבית", "row": r_str})

                priority_order = {
                    "מעבדה וקריאות שירות": 1,
                    "מלאי, פריטים ומחירים": 2,
                    "קופה והזמנות": 3,
                    "לקוחות": 4,
                    "דוחות": 5,
                    "תפריט כללי": 6,
                }
                sorted_menus = sorted(menus_found, key=lambda m: priority_order.get(m.get("category", "תפריט כללי"), 9))

                # 2. Crawl up to 6 key menu pages to pull live tables & sub-menus
                visited_urls = {str(land_resp.url)}
                for m_item in sorted_menus[:6]:
                    m_url = m_item["url"]
                    if m_url in visited_urls:
                        continue
                    visited_urls.add(m_url)
                    try:
                        p_resp = sess.get(m_url, params={"search": search_query} if search_query else None)
                        if p_resp.status_code != 200 or "login.aspx" in str(p_resp.url).lower():
                            continue
                        p_html = p_resp.text or ""
                        sub_menus = _extract_html_menus_and_links(p_html, NEWORDER_BASE_URL)
                        existing_urls = {x["url"] for x in menus_found}
                        for sm in sub_menus:
                            if sm["url"] not in existing_urls:
                                menus_found.append(sm)
                                existing_urls.add(sm["url"])

                        p_rows = _extract_html_table_rows(p_html)
                        if p_rows:
                            _ingest_neworder_rows_into_db(p_rows, m_item["title"])
                        pages_scanned.append({
                            "menu_title": m_item["title"],
                            "category": m_item["category"],
                            "url": m_url,
                            "total_rows": len(p_rows),
                            "sample_rows": [" | ".join(r[:8]) for r in p_rows[:5]],
                        })
                        if q_clean:
                            for r in p_rows:
                                r_str = " | ".join(r)
                                if q_clean in r_str.lower():
                                    search_matches.append({"source": m_item["title"], "row": r_str})
                    except Exception:
                        continue

                NEWORDER_SESSION_CACHE["discovered_pages"] = [m["url"] for m in menus_found]
                NEWORDER_SESSION_CACHE["menus_found"] = menus_found
                NEWORDER_SESSION_CACHE["pages_scanned"] = pages_scanned[:15]
                save_neworder_session_cache()
    except Exception as e_exp:
        return {
            "ok": True,
            "mode": auth_res.get("mode", ""),
            "note": f"החיבור פעיל ({e_exp})",
            "bridge_url": bridge_url,
            "landing_url": landing_url,
            "menus_found": menus_found,
            "pages_scanned": pages_scanned,
        }

    return {
        "ok": True,
        "mode": auth_res.get("mode", ""),
        "bridge_url": bridge_url,
        "last_bridge_sync": NEWORDER_SESSION_CACHE.get("last_bridge_sync", ""),
        "portal_url": POS_API_URL,
        "landing_url": landing_url,
        "company_configured": bool(company or NEWORDER_COMPANY),
        "username_configured": bool(username or NEWORDER_USERNAME),
        "password_configured": bool(password or NEWORDER_PASSWORD),
        "cookie_configured": bool(NEWORDER_COOKIE or NEWORDER_SESSION_CACHE.get("cookies")),
        "menus_count": len(menus_found),
        "menus_found": menus_found,
        "pages_scanned": pages_scanned,
        "search_query": search_query,
        "search_matches": search_matches[:15],
    }


