def is_customer_style_new_inquiry(text: str) -> bool:
    """
    Returns True if the incoming text clearly looks like a customer initiating a new inquiry
    (e.g., asking store hours, asking who the owner is, asking device prices, reporting a broken device,
    or asking to schedule a new appointment). Used so that when an Admin replies naturally without
    writing 'תשובה:', the server distinguishes Admin replies from customer test inquiries.
    """
    clean = (text or "").strip().lower()
    if not clean:
        return False
    # Explicit admin prefix, style/tikun command, or 3rd-person instruction to bot is NEVER a customer inquiry
    if is_admin_style_or_tikun_command(clean) or is_admin_bit_payment_directive(clean):
        return False
    if re.match(r"^(?:תשובה|תיקון|כלל|שישאל|תשאל|תגיד\s+לו|תמסור\s+לו|תכתוב\s+לו|תעדכן\s+אותו|שיכנס|שילחץ|שיבצע|צריך\s+לשלוח|תשלח\s+ללקוח)", clean):
        return False
    if is_pure_greeting(clean) or is_store_info_question(clean) or is_store_owner_question(clean):
        return True
    cust_sched_initiators = [
        "אפשר לקבוע", "אפשר לתאם", "רוצה לקבוע", "רוצה לתאם", "אשמח לקבוע", "אשמח לתאם",
        "מתי אפשר לקבוע", "מתי אפשר לתאם", "לקבוע תור", "לתאם תור", "לקבוע מחר",
        "תור לתיקון", "חור לתיקון", "תור למעבדה", "תור לרכוש", "תור לקנות", "תור לרכישת",
        "שלא יצטרך להמתין", "שלא אצטרך להמתין"
    ]
    if any(k in clean for k in cust_sched_initiators):
        return True
    cust_inquiry_phrases = [
        "כמה עולה", "מה המחיר", "יש לכם", "יש לי בעיה", "נשבר לי", "המכשיר שלי",
        "הטלפון שלי", "הפלאפון שלי", "אני צריך", "אני רוצה לרכוש", "אני רוצה לקנות",
        "האם אתם מתקנים", "אתם מתקנים", "מה ההבדל בין"
    ]
    if any(k in clean for k in cust_inquiry_phrases):
        return True
    return False

def handle_admin_tikun_or_style_command(message_text: str, sender_phone: str, raw_chat_id: str) -> dict:
    """
    Permanently learns a phrasing or style correction when Admin writes 'תיקון: ...'
    or instructs 'מעכשיו אל תשאל X אלא תכתוב Y' / 'במקום X תכתוב Y'.
    Updates learned_style_rules + rewrites learned_kb + updates active customer request if applicable.
    """
    clean_msg = auto_fix_common_hebrew_typos((message_text or "").strip())
    body = re.sub(r"^(?:תיקון|כלל\s+חדש|כלל\s+קבוע|שינוי\s+נוסח|נוסח\s+קבוע)\s*[:\-]\s*", "", clean_msg, flags=re.IGNORECASE).strip()

    # Check if Admin is specifying a "Instead of X write Y" / "From now on don't ask X rather write Y" rule
    m_instead = (
        re.search(
            r"(?:מעכשיו\s+)?(?:אל|לא)\s+(?:תשאל|ישאל|תכתוב|יכתוב|תרשום|ירשום|תגיד|יגיד)(?:\s+את\s+הלקוח|\s+לו)?\s+(.+?)\s+(?:אלא|אלה)\s+(?:תכתוב|יכתוב|תרשום|ירשום|תשאל|ישאל|תגיד|יגיד)?(?:\s+לו|\s+ללקוח)?\s*[:\x22\x27]?(.+?)[\x22\x27]?$",
            body,
            flags=re.IGNORECASE
        )
        or re.search(
            r"במקום\s+(?:לשאול|לכתוב|לרשום|להגיד)(?:\s+ללקוח|\s+לו)?\s+(.+?)\s+(?:תכתוב|יכתוב|תרשום|ירשום|תשאל|ישאל|תגיד|יגיד)(?:\s+לו|\s+ללקוח)?\s*[:\x22\x27]?(.+?)[\x22\x27]?$",
            body,
            flags=re.IGNORECASE
        )
    )

    if m_instead:
        raw_from = m_instead.group(1).strip(" .,!\x22'")
        raw_to = m_instead.group(2).strip(" .,!\x22'")
        if not raw_to.endswith("?") and any(q in raw_to for q in ["מה ", "איזה ", "איזו ", "האם ", "מתי ", "איך "]):
            raw_to += "?"

        # Map 3rd-person description of old phrase (e.g. "אם הוא רוצה להזמין את החלק") to actual 2nd-person bot phrases
        patterns_to_replace = [raw_from]
        if "להזמין את החלק" in raw_from or "להזמין עבורך את החלק" in raw_from:
            patterns_to_replace.extend([
                "האם תרצה שנזמין עבורך את החלק?",
                "האם תרצה שאזמין עבורך את החלק?",
                "האם תרצה שאזמין את החלק?",
                "האם תרצה להזמין את החלק?",
                "האם תרצה שנזמין את החלק?",
            ])
        else:
            adapted_from, _ = adapt_admin_answer(raw_from)
            if adapted_from and adapted_from not in patterns_to_replace:
                patterns_to_replace.append(adapted_from.rstrip(" 😃").strip())

        instruction_summary = f"במקום '{raw_from}' חובה לכתוב תמיד: '{raw_to}'"
        for pf in patterns_to_replace:
            save_permanent_style_rule(pf, raw_to, instruction_summary)

        confirm_reply = (
            f"✅ *הכלל והנוסח עודכנו באופן קבוע במערכת ובמאגר הזיכרון!*\n"
            f"🔄 *נוסח שהוחלף:* \x22{patterns_to_replace[-1]}\x22\n"
            f"✨ *הנוסח הקבוע החדש:* \x22{raw_to}\x22\n"
            f"(כל התשובות השמורות במאגר הידע עודכנו אוטומטית לנוסח החדש)."
        )
        send_whatsapp_message(sender_phone, confirm_reply, raw_chat_id)
        return {"ok": True, "admin_action": "permanent_style_rule_saved", "from": patterns_to_replace, "to": raw_to}

    # Otherwise, Admin wrote "תיקון: [הנוסח החדש]" directly
    adapted_new, is_in_prog = adapt_admin_answer(body)
    # Preserve Admin's exact wording if Admin wrote a direct 2nd-person sentence
    final_new_phrasing = adapted_new if adapted_new else body
    save_permanent_style_rule("", final_new_phrasing, f"הנחיית ניסוח קבועה מערן: {body}")

    # Also update the most recent learned_kb entry (and active customer request if one is pending)
    updated_kb_kw = ""
    try:
        conn = sqlite3.connect(DB_PATH)
        last_kb = conn.execute("SELECT id, keywords FROM learned_kb ORDER BY id DESC LIMIT 1").fetchone()
        if last_kb:
            conn.execute("UPDATE learned_kb SET answer = ? WHERE id = ?", (final_new_phrasing, last_kb[0]))
            updated_kb_kw = last_kb[1]
        # Check if there is a pending customer request waiting for an answer right now
        pend_req = conn.execute(
            "SELECT id, phone, request_text FROM customer_requests WHERE status = 'pending' AND phone != ? ORDER BY id DESC LIMIT 1",
            (sender_phone,)
        ).fetchone()
        if pend_req:
            target_cust = pend_req[1]
            send_whatsapp_message(target_cust, final_new_phrasing)
            save_chat_message(target_cust, "agent", final_new_phrasing)
            opts = extract_options_and_prices_from_text(final_new_phrasing)
            act_str = final_new_phrasing
            if opts:
                act_str += f" [OPTIONS_JSON:{json.dumps(opts, ensure_ascii=False)}]"
            conn.execute("UPDATE customer_requests SET status='awaiting_customer_reply', action_taken=? WHERE id=?", (act_str, pend_req[0]))
        conn.commit()
        conn.close()
        sync_learned_kb_to_json()
    except Exception as e:
        print(f"[Tikun Update Notice]: {e}")

    kb_note = f" (כולל עדכון התשובה הקבועה עבור '{updated_kb_kw}')" if updated_kb_kw else ""
    confirm_reply = (
        f"✅ *התיקון נשמר באופן קבוע במערכת{kb_note}!*\n"
        f"✨ *הנוסח המעודכן:* \x22{final_new_phrasing}\x22"
    )
    send_whatsapp_message(sender_phone, confirm_reply, raw_chat_id)
    return {"ok": True, "admin_action": "permanent_tikun_applied", "new_phrasing": final_new_phrasing}


def handle_admin_bit_payment_directive(admin_answer: str, target_pending, sender_phone: str, raw_chat_id: str) -> dict:
    """
    Handles when Admin hints or instructs the bot to send a Bit payment request to the customer
    (e.g. 'אתה צריך לשלוח ללקוח בקשה לשלוח ביט', 'תשלח לו בקשה להעביר ביט').
    Extracts the item name (e.g. 'מגן סיליקון') and price X from the conversation history (or Admin's message)
    and sends a formal Bit payment request to the customer without parroting Admin's words!
    """
    conn = sqlite3.connect(DB_PATH)
    if not target_pending:
        target_pending = conn.execute(
            "SELECT id, phone, request_text FROM customer_requests WHERE phone != ? ORDER BY id DESC LIMIT 1",
            (sender_phone,)
        ).fetchone()

    if not target_pending:
        conn.close()
        send_whatsapp_message(sender_phone, "⚠️ לא נמצאה פניית לקוח פתוחה לשליחת בקשת תשלום בביט.", raw_chat_id)
        return {"ok": False, "error": "no_active_customer_for_bit"}

    req_id, target_cust_phone, req_text = target_pending[0], target_pending[1], target_pending[2] or ""
    prev_act_row = conn.execute("SELECT action_taken FROM customer_requests WHERE id=?", (req_id,)).fetchone()
    prev_act_str = (prev_act_row[0] if prev_act_row else "") or ""
    full_hist = get_recent_chat_history(target_cust_phone, limit=16)

    # 1. Check if Admin explicitly mentioned a price in this directive (excluding the Bit phone number)
    admin_clean_no_phone = admin_answer.replace("052-4043644", "").replace("0524043644", "")
    explicit_adm_price = extract_price_nis(admin_clean_no_phone)

    # 2. Look up the selected option & its price from the customer's request and conversation history
    latest_cust_q = extract_latest_customer_question(req_text)
    sel_info = find_selected_option_and_price(latest_cust_q or req_text, prev_act_str, full_hist, req_text)
    if not sel_info.get("matched"):
        # Also scan customer lines in full_hist from newest to oldest
        cust_lines = [l.replace("[לקוח]:", "").strip() for l in full_hist.split("\n") if l.strip().startswith("[לקוח]:")]
        for cl in reversed(cust_lines):
            cand = find_selected_option_and_price(cl, prev_act_str, full_hist, req_text)
            if cand.get("matched"):
                sel_info = cand
                break

    item_name = sel_info.get("name") if sel_info.get("matched") else ""
    item_price = explicit_adm_price or (sel_info.get("price") if sel_info.get("matched") else "")

    if not item_price:
        m_saved_p = re.search(r"\[PRICE:(\d{2,4})\]", prev_act_str + " " + req_text)
        item_price = m_saved_p.group(1) if m_saved_p else (extract_price_nis(prev_act_str) or extract_price_nis(full_hist))

    if not item_name:
        if "סיליקון" in auto_fix_common_hebrew_typos(req_text + " " + full_hist):
            item_name = "מגן סיליקון"
        elif "זכוכית" in (req_text + " " + full_hist):
            item_name = "מגן זכוכית"
        else:
            item_name = "הפריט המבוקש"

    if item_price:
        cust_bit_msg = (
            f"לצורך הזמנת *{item_name}* שמחירו *{item_price} ₪*, אנא העבר כעת *{item_price} ₪* בביט (Bit) למספר:\n"
            f"📱 *{BIT_PAYMENT_PHONE}* (ערן נקר - נעם שיח)\n\n"
            f"לאחר ההעברה, שלח לנו כאן עדכון או צילום מסך ונדאג להזמין ולשמור עבורך מיד! 😃"
        )
        act_update = f"נשלחו פרטי תשלום בביט עבור {item_name} ({item_price} ₪ ל-{BIT_PAYMENT_PHONE}) [PRICE:{item_price}]"
    else:
        cust_bit_msg = (
            f"לצורך הזמנת *{item_name}*, ניתן להעביר תשלום בביט (Bit) למספר:\n"
            f"📱 *{BIT_PAYMENT_PHONE}* (ערן נקר - נעם שיח)\n\n"
            f"לאחר ההעברה, שלח לנו כאן עדכון או צילום מסך ונדאג להזמין עבורך מיד! 😃"
        )
        act_update = f"נשלחו פרטי תשלום בביט עבור {item_name} (ל-{BIT_PAYMENT_PHONE})"

    conn.execute("UPDATE customer_requests SET status='awaiting_bit_payment', action_taken=? WHERE id=?", (act_update, req_id))
    conn.commit()
    conn.close()

    send_whatsapp_message(target_cust_phone, cust_bit_msg)
    save_chat_message(target_cust_phone, "agent", cust_bit_msg)

    price_str_adm = f" על סך *{item_price} ₪*" if item_price else ""
    confirm_adm = (
        f"✅ נשלחה ללקוח ({target_cust_phone}) בקשת תשלום מסודרת בביט{price_str_adm} עבור *{item_name}* למספר {BIT_PAYMENT_PHONE}!"
    )
    send_whatsapp_message(sender_phone, confirm_adm, raw_chat_id)
    return {
        "ok": True,
        "admin_action": "bit_payment_request_sent_from_directive",
        "customer": target_cust_phone,
        "item": item_name,
        "price": item_price,
    }


async def unified_whatsapp_webhook(req: Request):
    print(f"[HTTP Incoming] Received {req.method} to {req.url.path}")
    try:
        payload = await req.json()
    except Exception as e:
        print(f"[HTTP Incoming Error]: Cannot parse JSON: {e}")
        return JSONResponse(content={"ok": False, "error": "Invalid JSON"}, status_code=200)

    # 1. Unwrap if wrapped in {"receiptId": ..., "body": {...}}
    if isinstance(payload, dict) and "body" in payload and isinstance(payload["body"], dict):
        payload = payload["body"]

    # 2. Strictly process ONLY incomingMessageReceived when typeWebhook is present
    type_webhook = payload.get("typeWebhook", "")
    print(f"[Payload Received]: typeWebhook={type_webhook}")
    if type_webhook and type_webhook != "incomingMessageReceived":
        return {"ok": True, "note": f"Ignored non-incoming webhook: {type_webhook}"}

    # 3. Extract Sender Phone cleanly & ignore group chats or self-messages
    sender_data = payload.get("senderData", {}) if isinstance(payload.get("senderData"), dict) else {}
    message_data = payload.get("messageData", {}) if isinstance(payload.get("messageData"), dict) else {}
    instance_data = payload.get("instanceData", {}) if isinstance(payload.get("instanceData"), dict) else {}

    raw_chat_id = str(sender_data.get("chatId", "") or payload.get("chatId", ""))
    if raw_chat_id.endswith("@g.us"):
        print(f"[Ignored Group Message] chatId={raw_chat_id}")
        return {"ok": True, "note": "Ignored group chat message"}

    # Prefer a @c.us phone identifier if either sender or chatId has it
    raw_sender_field = str(sender_data.get("sender", "") or payload.get("sender", ""))
    if "@c.us" in raw_sender_field:
        raw_sender = raw_sender_field
    elif "@c.us" in raw_chat_id:
        raw_sender = raw_chat_id
    else:
        raw_sender = (
            raw_chat_id
            or raw_sender_field
            or str(payload.get("senderPhone", ""))
            or str(payload.get("from", ""))
        )

    clean_sender_raw = str(raw_sender).split("@")[0].split(":")[0]
    sender_phone = normalize_phone(clean_sender_raw)

    # Guard against bot replying to its own instance WID
    bot_own_phone = normalize_phone(str(instance_data.get("wid", "")))
    if bot_own_phone and sender_phone and bot_own_phone == sender_phone and raw_sender_field == str(instance_data.get("wid", "")):
        print(f"[Ignored Self Message] sender={sender_phone} matches instance wid={bot_own_phone}")
        return {"ok": True, "note": "Ignored self message"}

    # 4. Extract Message Text across all message types
    type_msg = message_data.get("typeMessage", "")
    message_text = ""
    if type_msg == "textMessage":
        message_text = message_data.get("textMessageData", {}).get("textMessage", "")
    elif type_msg in ["extendedTextMessage", "quotedMessage"]:
        message_text = (
            message_data.get("extendedTextMessageData", {}).get("text", "")
            or message_data.get("quotedMessage", {}).get("textMessage", "")
            or message_data.get("quotedMessage", {}).get("text", "")
        )
    elif type_msg in ["imageMessage", "videoMessage", "documentMessage", "audioMessage"]:
        message_text = message_data.get("fileMessageData", {}).get("caption", "")
    elif type_msg == "buttonsResponseMessage":
        message_text = (
            message_data.get("buttonsResponseMessage", {}).get("selectedDisplayText", "")
            or message_data.get("buttonsResponseMessage", {}).get("selectedButtonId", "")
        )
    elif type_msg == "templateButtonsReplyMessage":
        message_text = (
            message_data.get("templateButtonReplyMessage", {}).get("selectedDisplayText", "")
            or message_data.get("templateButtonReplyMessage", {}).get("selectedId", "")
        )
    elif type_msg == "listResponseMessage":
        message_text = (
            message_data.get("listResponseMessage", {}).get("title", "")
            or message_data.get("listResponseMessage", {}).get("singleSelectReply", {}).get("selectedRowId", "")
        )

    if not message_text:
        message_text = (
            message_data.get("textMessageData", {}).get("textMessage", "")
            or message_data.get("extendedTextMessageData", {}).get("text", "")
            or payload.get("text", "")
            or payload.get("message", "")
        )
    message_text = (message_text or "").strip()

    if not sender_phone:
        print(f"[Ignored] Missing sender_phone: typeMessage={type_msg}")
        return {"ok": True, "note": "Ignored missing sender"}
    if not message_text and type_msg == "documentMessage":
        doc_fn = str(message_data.get("fileMessageData", {}).get("fileName") or "inventory.xlsx")
        message_text = f"[ADMIN_DOC_UPLOAD:{doc_fn}]"
    if not message_text and type_msg == "imageMessage":
        # Check if customer is awaiting Bit payment confirmation and sent a screenshot without caption
        try:
            _c_img = sqlite3.connect(DB_PATH)
            _r_img = _c_img.execute(
                "SELECT id FROM customer_requests WHERE (phone = ? OR phone LIKE ?) AND status = 'awaiting_bit_payment' LIMIT 1",
                (sender_phone, f"%{sender_phone[-9:]}%")
            ).fetchone()
            _c_img.close()
            if _r_img:
                message_text = "שילמתי בביט (צילום מסך)"
        except Exception:
            pass
    if not message_text:
        print(f"[Ignored] Non-message webhook event: sender={sender_phone}, typeMessage={type_msg}")
        return {"ok": True, "note": "Ignored non-text or system event"}

    print(f"[Incoming WhatsApp] From {sender_phone}: {message_text}")

    # Recognize both of Eran's numbers as authorized admin numbers
    admin_numbers_set = {
        normalize_phone(ADMIN_WHATSAPP_PHONE),
        "972553164770",
        "972524043644"
    }

    # Extract Quoted Message early (if user/admin swiped to reply in WhatsApp)
    quoted_text = ""
    if isinstance(message_data.get("quotedMessage"), dict):
        quoted_text = str(message_data["quotedMessage"].get("textMessage") or message_data["quotedMessage"].get("text") or "")
    elif isinstance(message_data.get("extendedTextMessageData"), dict):
        q_obj = message_data["extendedTextMessageData"].get("quotedMessage", {})
        if isinstance(q_obj, dict):
            quoted_text = str(q_obj.get("textMessage") or q_obj.get("text") or "")

    is_admin_swipe_reply = bool(
        quoted_text and (
            "פנייה מלקוח שדורשת את תשובתך" in quoted_text
            or "שאלה מלקוח שדורשת את תשובתך" in quoted_text
            or "עדכון שעה מלקוח" in quoted_text
            or re.search(r"\[#REQ-\d+\]", quoted_text, re.IGNORECASE)
        )
    )

    # Check if Admin is replying naturally without writing "תשובה:" (when a customer request is awaiting Admin)
    has_explicit_admin_prefix = (
        "תשובה:" in message_text
        or message_text.startswith("תשובה ")
        or is_admin_swipe_reply
        or bool(re.search(r"\[?#REQ-\d+\]?", message_text, re.IGNORECASE))
    )
    # 0.A Check if Admin is replying to an Uncertain Typo Confirmation prompt ("האם אתה בטוח שזה הנוסח הנכון?")
    bypass_typo_check = False
    if sender_phone in admin_numbers_set and sender_phone in PENDING_ADMIN_TYPO_CONFIRMATIONS:
        pending_typo = PENDING_ADMIN_TYPO_CONFIRMATIONS.pop(sender_phone)
        reply_low = message_text.strip().lower()
        if reply_low in ["תקן", "כן תקן", "כן", "תשלח מתוקן", "מתוקן", "אשר תיקון"]:
            message_text = pending_typo["suggested_full_msg"]
            bypass_typo_check = True
        elif reply_low in ["שלח ככה", "בטוח", "כן בטוח", "המקורי", "לא לתקן", "כמו שכתבתי"]:
            message_text = pending_typo["original_full_msg"]
            bypass_typo_check = True
        else:
            # Admin wrote a fresh phrasing
            bypass_typo_check = True

    # 0.B Permanent Style / Phrasing Rule Interceptor ('תיקון:', 'מעכשיו אל תשאל... אלא תכתוב...')
    if sender_phone in admin_numbers_set and is_admin_style_or_tikun_command(message_text):
        return handle_admin_tikun_or_style_command(message_text, sender_phone, raw_chat_id)

    # 0.C Operational Bit Payment Directive Interceptor ('צריך לשלוח ללקוח בקשה לשלוח ביט')
    if sender_phone in admin_numbers_set and is_admin_bit_payment_directive(message_text):
        return handle_admin_bit_payment_directive(message_text, None, sender_phone, raw_chat_id)

    # 0.D1 Direct WhatsApp Inventory File Upload (Admin sends .xlsx / .xls / .csv / .txt directly in WhatsApp!)
    if sender_phone in admin_numbers_set and type_msg == "documentMessage":
        file_meta = message_data.get("fileMessageData", {}) if isinstance(message_data.get("fileMessageData"), dict) else {}
        dl_url = str(file_meta.get("downloadUrl") or "").strip()
        doc_fn = str(file_meta.get("fileName") or "inventory.xlsx").strip()
        if dl_url:
            try:
                f_resp = http_session.get(dl_url, timeout=15.0)
                if f_resp.status_code == 200 and f_resp.content:
                    parsed_rows = _parse_inventory_file_bytes(f_resp.content, doc_fn)
                    ing_res = _ingest_neworder_rows_into_db(parsed_rows, f"קובץ ווצאפ ({doc_fn})")
                    conn = sqlite3.connect(DB_PATH)
                    total_pos_now = conn.execute("SELECT COUNT(*) FROM pos_inventory").fetchone()[0]
                    sample_pos = conn.execute("SELECT product_name, single_price FROM pos_inventory ORDER BY id DESC LIMIT 6").fetchall()
                    conn.close()
                    sample_str = "\n".join([f"• *{r[0]}*: סביב {r[1]} ₪" for r in sample_pos if r[0] and r[1]])
                    msg_doc_ok = (
                        f"✅ *קובץ המלאי ({doc_fn}) נקלט ונטען לסוכן בהצלחה!* 📦🎉\n"
                        f"• *מוצרים שנוספו/עודכנו בקובץ זה:* {ing_res['items_added']}\n"
                        f"• *סה\"כ מוצרים במלאי הסוכן כרגע:* {total_pos_now}\n"
                        f"• *חומת אש:* מחירי עלות ושמות ספקים/יבואנים סוננו אוטומטית (נשמר אך ורק מחיר המכירה לצרכן!).\n\n"
                        + (f"📋 *דגימת מוצרים שנטענו:*\n{sample_str}" if sample_str else "")
                    )
                    send_whatsapp_message(sender_phone, msg_doc_ok, raw_chat_id)
                    return {"ok": True, "admin_action": "whatsapp_inventory_file_imported", "items_added": ing_res["items_added"], "total_pos_items": total_pos_now}
            except Exception as e_doc:
                send_whatsapp_message(sender_phone, f"⚠️ שגיאה בקריאת קובץ המלאי ({doc_fn}): {e_doc}", raw_chat_id)
                return {"ok": False, "error": str(e_doc)}

    # 0.D2 Direct WhatsApp Text Inventory Import ('עדכון מלאי:' / 'טעינת מלאי:' followed by lines of 'מוצר - מחיר')
    if sender_phone in admin_numbers_set and re.match(r"^(?:עדכון\s+מלאי|טעינת\s+מלאי|הוספת\s+מלאי)\s*[:\-]\s*(.+)$", message_text.strip(), flags=re.IGNORECASE | re.DOTALL):
        m_inv_txt = re.match(r"^(?:עדכון\s+מלאי|טעינת\s+מלאי|הוספת\s+מלאי)\s*[:\-]\s*(.+)$", message_text.strip(), flags=re.IGNORECASE | re.DOTALL)
        inv_body = m_inv_txt.group(1).strip()
        parsed_rows = _parse_inventory_file_bytes(inv_body.encode("utf-8"), "whatsapp_text.txt")
        ing_res = _ingest_neworder_rows_into_db(parsed_rows, "עדכון מלאי בווצאפ")
        conn = sqlite3.connect(DB_PATH)
        total_pos_now = conn.execute("SELECT COUNT(*) FROM pos_inventory").fetchone()[0]
        sample_pos = conn.execute("SELECT product_name, single_price FROM pos_inventory ORDER BY id DESC LIMIT 6").fetchall()
        conn.close()
        sample_str = "\n".join([f"• *{r[0]}*: סביב {r[1]} ₪" for r in sample_pos if r[0] and r[1]])
        msg_txt_ok = (
            f"✅ *המלאי עודכן בהצלחה בזיכרון הסוכן!* 📦\n"
            f"• *מוצרים שנקלטו בהודעה זו:* {ing_res['items_added']}\n"
            f"• *סה\"כ מוצרים במלאי הסוכן כרגע:* {total_pos_now}\n\n"
            + (f"📋 *מוצרים אחרונים שנטענו:*\n{sample_str}" if sample_str else "")
        )
        send_whatsapp_message(sender_phone, msg_txt_ok, raw_chat_id)
        return {"ok": True, "admin_action": "whatsapp_inventory_text_imported", "items_added": ing_res["items_added"], "total_pos_items": total_pos_now}

    # 0.D3 Live NewOrder POS & Lab Menu Diagnostic Command via WhatsApp ('בדיקת קופה', 'מלאי קופה', 'תפריטי קופה', 'בדיקת קופה: f21')
    if sender_phone in admin_numbers_set and re.match(
        r"^(?:בדיקת\s+קופה|מלאי\s+קופה|תפריטי\s+קופה|בדיקת\s+חיבור\s+לקופה|סנכרון\s+קופה|בדיקת\s+ניו\s+אורדר|בדיקת\s+neworder)(?:\s*[:\-]\s*(.*))?$",
        message_text.strip(),
        flags=re.IGNORECASE,
    ):
        m_pos_cmd = re.match(
            r"^(?:בדיקת\s+קופה|מלאי\s+קופה|תפריטי\s+קופה|בדיקת\s+חיבור\s+לקופה|סנכרון\s+קופה|בדיקת\s+ניו\s+אורדר|בדיקת\s+neworder)(?:\s*[:\-]\s*(.*))?$",
            message_text.strip(),
            flags=re.IGNORECASE,
        )
        pos_q = (m_pos_cmd.group(1) or "").strip() if m_pos_cmd else ""
        exp_res = explore_neworder_menus_and_data(search_query=pos_q)

        # Always check actual SQLite pos_inventory & lab_repairs counts so we report 100% honest data!
        db_items_cnt = 0
        db_repairs_cnt = 0
